


function sha256Pure(ascii) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  let lengthProperty = 'length';
  let i, j;
  let result = '';

  const words = [];
  const asciiBitLength = ascii[lengthProperty] * 8;

  let hash = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
  ];

  const k = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
  ];

  let compositeClear = '\x80';
  while ((ascii[lengthProperty] + compositeClear[lengthProperty]) % 64 !== 56) {
    compositeClear += '\x00';
  }
  ascii += compositeClear;

  for (i = 0; i < ascii[lengthProperty]; i++) {
    j = ascii.charCodeAt(i);
    if (j >> 8) return;
    words[i >> 2] |= j << ((3 - i) % 4) * 8;
  }
  words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
  words[words[lengthProperty]] = (asciiBitLength);

  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash;
    hash = hash.slice(0, 8);

    for (i = 0; i < 64; i++) {
      const i2 = i + j;
      const w15 = w[i - 15], w2 = w[i - 2];

      const a = hash[0], e = hash[4];
      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ ((~e) & hash[6]))
        + k[i]
        + (w[i] = (i < 16) ? w[i] : (
          w[i - 16]
          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
          + w[i - 7]
          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
        ) | 0
      );
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
    }

    for (i = 0; i < 8; i++) {
      hash[i] = (hash[i] + oldHash[i]) | 0;
    }
  }

  for (i = 0; i < 8; i++) {
    for (let b = 3; b >= 0; b--) {
      const byte = (hash[i] >> (b * 8)) & 255;
      result += (byte < 16 ? '0' : '') + byte.toString(16);
    }
  }
  return result;
}

if (typeof module !== 'undefined') module.exports = sha256Pure;





window.appLog = function(tag, msg, data = null) {
  const t = new Date().toLocaleTimeString();
  const line = `[${t}] [${tag}] ${msg} ${data ? (typeof data === 'object' ? JSON.stringify(data) : data) : ''}`;
  console.log(line);
  if (!window._debugLogs) window._debugLogs = [];
  window._debugLogs.push(line);
  const logEl = document.getElementById('debug-log-content');
  if (logEl) {
    logEl.textContent = window._debugLogs.slice(-40).join('\n');
    logEl.scrollTop = logEl.scrollHeight;
  }
};

class SoundEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.clipCache = new Map();
    this.tuneTimer = null;
    this.stepTimer = null;
    this.isTuneActive = false;
    this.activeTrackAudio = null;
    this.lastAudioUrl = null;
    this.lastMovieTitle = null;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
        window.appLog('AUDIO', 'AudioContext initialized. State: ' + this.ctx.state);
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      try {
        this.ctx.resume();
        window.appLog('AUDIO', 'AudioContext resumed. State: ' + this.ctx.state);
      } catch (e) {}
    }
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.muted) this.stopMovieTune();
    return this.muted;
  }

  unlockAudio() {
    this.init();
    if (this.ctx && this.ctx.state === 'suspended') {
      try { this.ctx.resume(); } catch (e) {}
    }

    if (this.ctx && !this.audioUnlocked) {
      try {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        gain.gain.value = 0.0001;
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(0);
        osc.stop(this.ctx.currentTime + 0.05);
        this.audioUnlocked = true;
        window.appLog('AUDIO', 'Web Audio hardware unlocked successfully');
      } catch (e) {}
    }
  }

  

  playTick(urgent = false) {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(urgent ? 880 : 540, now);
      osc.frequency.exponentialRampToValueAtTime(urgent ? 440 : 260, now + 0.05);

      gain.gain.setValueAtTime(urgent ? 0.25 : 0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + 0.05);
    } catch (e) {}
  }

  playCorrect() {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const notes = [523.25, 659.25, 783.99, 1046.50];

      notes.forEach((freq, index) => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, now + index * 0.08);

        gain.gain.setValueAtTime(0.001, now + index * 0.08);
        gain.gain.linearRampToValueAtTime(0.2, now + index * 0.08 + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, now + index * 0.08 + 0.3);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now + index * 0.08);
        osc.stop(now + index * 0.08 + 0.3);
      });
    } catch (e) {}
  }

  playWrong() {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(150, now);
      osc.frequency.linearRampToValueAtTime(80, now + 0.25);

      gain.gain.setValueAtTime(0.18, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + 0.25);
    } catch (e) {}
  }

  playRoundStart() {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const chords = [329.63, 440, 554.37];

      chords.forEach(freq => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, now);

        gain.gain.setValueAtTime(0.001, now);
        gain.gain.linearRampToValueAtTime(0.15, now + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.4);
      });
    } catch (e) {}
  }

  playVictory() {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;

    try {
      const now = this.ctx.currentTime;
      const fanfare = [
        { f: 523.25, d: 0.15, t: 0 },
        { f: 523.25, d: 0.15, t: 0.18 },
        { f: 523.25, d: 0.15, t: 0.36 },
        { f: 659.25, d: 0.4, t: 0.54 },
        { f: 783.99, d: 0.4, t: 0.96 },
        { f: 1046.50, d: 0.8, t: 1.38 }
      ];

      fanfare.forEach(note => {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'triangle';
        osc.frequency.setValueAtTime(note.f, now + note.t);

        gain.gain.setValueAtTime(0.001, now + note.t);
        gain.gain.linearRampToValueAtTime(0.25, now + note.t + 0.03);
        gain.gain.exponentialRampToValueAtTime(0.001, now + note.t + note.d);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now + note.t);
        osc.stop(now + note.t + note.d);
      });
    } catch (e) {}
  }

  

  fetchSongPreviewUrl(query) {
    if (!query) return Promise.resolve(null);
    if (!this.clipCache) this.clipCache = new Map();
    if (this.clipCache.has(query)) {
      window.appLog('AUDIO', 'Cache hit for query: ' + query);
      return Promise.resolve(this.clipCache.get(query));
    }

    window.appLog('AUDIO', 'Querying iTunes API for: ' + query);

    return new Promise((resolve) => {
      const callbackName = 'itunes_cb_' + Math.random().toString(36).substr(2, 9);
      const searchTerms = encodeURIComponent(query.trim() + ' bollywood');
      const script = document.createElement('script');
      script.src = `https://itunes.apple.com/search?term=${searchTerms}&media=music&entity=song&country=IN&limit=1&callback=${callbackName}`;

      let resolved = false;
      const timeout = setTimeout(() => {
        if (!resolved) {
          resolved = true;
          cleanup();
          window.appLog('AUDIO', 'iTunes API timed out for query: ' + query);
          resolve(null);
        }
      }, 3500);

      const cleanup = () => {
        clearTimeout(timeout);
        try { delete window[callbackName]; } catch (e) {}
        if (script.parentNode) script.parentNode.removeChild(script);
      };

      window[callbackName] = (data) => {
        if (resolved) return;
        resolved = true;
        cleanup();
        if (data && data.results && data.results.length > 0 && data.results[0].previewUrl) {
          const track = {
            audioUrl: data.results[0].previewUrl,
            trackName: data.results[0].trackName,
            artistName: data.results[0].artistName
          };
          this.clipCache.set(query, track);
          window.appLog('AUDIO', `iTunes track found: "${track.trackName}" by ${track.artistName}`);
          window.appLog('AUDIO', `Preview URL: ${track.audioUrl}`);
          resolve(track);
        } else {
          window.appLog('AUDIO', 'No preview URL in iTunes response');
          resolve(null);
        }
      };

      script.onerror = (e) => {
        if (!resolved) {
          resolved = true;
          cleanup();
          window.appLog('AUDIO', 'iTunes JSONP script network error');
          resolve(null);
        }
      };

      document.body.appendChild(script);
    });
  }

  async getAudioSourceForMovie(movieTitle, songQuery) {
    const slug = (movieTitle || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const localM4a = `audio/${slug}.m4a`;
    const localMp3 = `audio/${slug}.mp3`;

    
    try {
      const res = await fetch(localM4a, { method: 'HEAD' });
      if (res.ok) {
        window.appLog('AUDIO', `Found local same-origin audio: ${localM4a}`);
        return localM4a;
      }
    } catch (e) {}

    try {
      const res = await fetch(localMp3, { method: 'HEAD' });
      if (res.ok) {
        window.appLog('AUDIO', `Found local same-origin audio: ${localMp3}`);
        return localMp3;
      }
    } catch (e) {}

    
    const track = await this.fetchSongPreviewUrl(songQuery || (movieTitle + ' bollywood song'));
    if (track && track.audioUrl) {
      return track.audioUrl;
    }

    return null;
  }

  async playMovieTuneHint(movieTitle = '', songQuery = '', audioUrl = null, maxSeconds = 20) {
    if (this.muted) return;
    this.stopMovieTune();

    this.lastAudioUrl = audioUrl;
    this.lastMovieTitle = movieTitle;

    window.appLog('AUDIO', `playMovieTuneHint invoked for: "${movieTitle}"`);

    
    if (!this.lastAudioUrl) {
      this.lastAudioUrl = await this.getAudioSourceForMovie(movieTitle, songQuery);
    }

    
    let playedOnline = false;
    if (this.lastAudioUrl) {
      playedOnline = await this.playActualAudioFile(this.lastAudioUrl, maxSeconds);
    }

    
    if (!playedOnline) {
      window.appLog('AUDIO', 'Starting rich multi-harmonic acoustic melody');
      this.playSynthesizedMovieTune(movieTitle, maxSeconds);
    }
  }

  playActualAudioFile(url, maxSeconds = 20) {
    window.appLog('AUDIO', 'Attempting background play of: ' + url);
    return new Promise((resolve) => {
      try {
        if (this.activeTrackAudio) {
          this.activeTrackAudio.pause();
          this.activeTrackAudio = null;
        }

        const audio = new Audio();
        audio.preload = 'auto';
        audio.playsInline = true;
        audio.src = url;
        audio.volume = 1.0;
        this.activeTrackAudio = audio;

        const playPromise = audio.play();
        if (playPromise !== undefined) {
          playPromise.then(() => {
            window.appLog('AUDIO', 'SUCCESS! Audio track is actively playing.');
            this.tuneTimer = setTimeout(() => this.stopMovieTune(), maxSeconds * 1000);
            resolve(true);
          }).catch(err => {
            window.appLog('AUDIO', `Background play blocked by OS: ${err.name} - ${err.message}`);
            resolve(false);
          });
        } else {
          resolve(false);
        }
      } catch (err) {
        window.appLog('AUDIO', 'Exception in playActualAudioFile: ' + err.message);
        resolve(false);
      }
    });
  }

  forcePlayActualAudio() {
    this.stopMovieTune();
    window.appLog('AUDIO', '1-Tap Force Play triggered. URL: ' + (this.lastAudioUrl || 'None'));
    if (!this.lastAudioUrl) {
      window.appLog('AUDIO', 'No audio URL, using acoustic melody');
      if (this.lastMovieTitle) this.playSynthesizedMovieTune(this.lastMovieTitle, 20);
      return;
    }

    try {
      const audio = new Audio();
      audio.preload = 'auto';
      audio.playsInline = true;
      audio.src = this.lastAudioUrl;
      audio.volume = 1.0;
      this.activeTrackAudio = audio;

      const p = audio.play();
      if (p !== undefined) {
        p.then(() => {
          window.appLog('AUDIO', 'SUCCESS! iPhone is playing actual song track.');
          this.tuneTimer = setTimeout(() => this.stopMovieTune(), 20000);
        }).catch(e => {
          window.appLog('AUDIO', `iPhone 1-tap playback rejected: ${e.name} - ${e.message}`);
          if (this.lastMovieTitle) this.playSynthesizedMovieTune(this.lastMovieTitle, 20);
        });
      }
    } catch (e) {
      window.appLog('AUDIO', 'Exception in forcePlay: ' + e.message);
      if (this.lastMovieTitle) this.playSynthesizedMovieTune(this.lastMovieTitle, 20);
    }
  }

  

  
  playAcousticNote(freq, duration = 0.3) {
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') {
      try { this.ctx.resume(); } catch (e) {}
    }

    try {
      const now = this.ctx.currentTime;

      
      const osc1 = this.ctx.createOscillator();
      const gain1 = this.ctx.createGain();
      osc1.type = 'triangle';
      osc1.frequency.setValueAtTime(freq, now);

      gain1.gain.setValueAtTime(0.0001, now);
      gain1.gain.linearRampToValueAtTime(0.24, now + 0.02);
      gain1.gain.exponentialRampToValueAtTime(0.0001, now + duration);

      osc1.connect(gain1);
      gain1.connect(this.ctx.destination);
      osc1.start(now);
      osc1.stop(now + duration);

      
      const osc2 = this.ctx.createOscillator();
      const gain2 = this.ctx.createGain();
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(freq * 2, now);

      gain2.gain.setValueAtTime(0.0001, now);
      gain2.gain.linearRampToValueAtTime(0.08, now + 0.02);
      gain2.gain.exponentialRampToValueAtTime(0.0001, now + duration);

      osc2.connect(gain2);
      gain2.connect(this.ctx.destination);
      osc2.start(now);
      osc2.stop(now + duration);
    } catch (e) {}
  }

  getMovieMelodyPattern(movieTitle = '') {
    const titleNorm = (movieTitle || '').toLowerCase().replace(/[^a-z0-9]/g, '');

    
    const C4 = 261.63, D4 = 293.66, E4 = 329.63, F4 = 349.23, G4 = 392.00, A4 = 440.00, B4 = 493.88;
    const C5 = 523.25, D5 = 587.33, E5 = 659.25, F5 = 698.46, G5 = 783.99, A5 = 880.00;
    const Bb4 = 466.16, Eb4 = 311.13, Fs4 = 369.99, Gs4 = 415.30, Cs5 = 554.37;

    if (titleNorm.includes('3idiots')) {
      
      return [
        { f: G4, d: 0.22 }, { f: C5, d: 0.22 }, { f: E5, d: 0.22 }, { f: G5, d: 0.4 },
        { f: E5, d: 0.22 }, { f: F5, d: 0.22 }, { f: E5, d: 0.22 }, { f: D5, d: 0.45 }
      ];
    } else if (titleNorm.includes('lagaan')) {
      
      return [
        { f: D4, d: 0.3 }, { f: F4, d: 0.3 }, { f: G4, d: 0.4 }, { f: A4, d: 0.3 },
        { f: C5, d: 0.3 }, { f: D5, d: 0.5 }, { f: A4, d: 0.3 }, { f: G4, d: 0.4 }
      ];
    } else if (titleNorm.includes('dilchahtahai')) {
      
      return [
        { f: E4, d: 0.25 }, { f: G4, d: 0.25 }, { f: A4, d: 0.4 }, { f: G4, d: 0.25 },
        { f: C5, d: 0.35 }, { f: B4, d: 0.25 }, { f: A4, d: 0.5 }
      ];
    } else if (titleNorm.includes('dhoom')) {
      
      return [
        { f: D5, d: 0.18 }, { f: D5, d: 0.18 }, { f: F5, d: 0.28 }, { f: G5, d: 0.28 },
        { f: F5, d: 0.18 }, { f: D5, d: 0.28 }, { f: C5, d: 0.28 }, { f: D5, d: 0.55 }
      ];
    } else if (titleNorm.includes('kalhonaaho')) {
      
      return [
        { f: E4, d: 0.35 }, { f: G4, d: 0.3 }, { f: A4, d: 0.35 }, { f: B4, d: 0.3 },
        { f: C5, d: 0.45 }, { f: B4, d: 0.3 }, { f: A4, d: 0.35 }, { f: G4, d: 0.55 }
      ];
    } else if (titleNorm.includes('jabwemet')) {
      
      return [
        { f: G4, d: 0.18 }, { f: G4, d: 0.18 }, { f: A4, d: 0.18 }, { f: C5, d: 0.28 },
        { f: D5, d: 0.28 }, { f: C5, d: 0.18 }, { f: A4, d: 0.18 }, { f: G4, d: 0.38 }
      ];
    } else if (titleNorm.includes('dangal')) {
      
      return [
        { f: D4, d: 0.18 }, { f: D4, d: 0.18 }, { f: F4, d: 0.25 }, { f: D4, d: 0.18 },
        { f: G4, d: 0.32 }, { f: F4, d: 0.18 }, { f: D4, d: 0.4 }
      ];
    } else if (titleNorm.includes('gullyboy')) {
      
      return [
        { f: C4, d: 0.18 }, { f: C4, d: 0.18 }, { f: Eb4, d: 0.28 }, { f: F4, d: 0.28 },
        { f: G4, d: 0.35 }, { f: F4, d: 0.18 }, { f: C4, d: 0.38 }
      ];
    } else if (titleNorm.includes('pathaan')) {
      
      return [
        { f: A4, d: 0.22 }, { f: C5, d: 0.22 }, { f: D5, d: 0.3 }, { f: E5, d: 0.32 },
        { f: D5, d: 0.22 }, { f: C5, d: 0.22 }, { f: A4, d: 0.45 }
      ];
    } else if (titleNorm.includes('animal')) {
      
      return [
        { f: D4, d: 0.18 }, { f: F4, d: 0.18 }, { f: G4, d: 0.25 }, { f: G4, d: 0.25 },
        { f: A4, d: 0.18 }, { f: G4, d: 0.18 }, { f: F4, d: 0.18 }, { f: D4, d: 0.45 }
      ];
    } else if (titleNorm.includes('yehjaawaani') || titleNorm.includes('yjhd')) {
      
      return [
        { f: D5, d: 0.18 }, { f: D5, d: 0.18 }, { f: F5, d: 0.25 }, { f: G5, d: 0.3 },
        { f: F5, d: 0.18 }, { f: D5, d: 0.25 }, { f: C5, d: 0.25 }, { f: D5, d: 0.4 }
      ];
    } else if (titleNorm.includes('shershaah')) {
      
      return [
        { f: E4, d: 0.35 }, { f: G4, d: 0.35 }, { f: A4, d: 0.45 }, { f: B4, d: 0.3 },
        { f: C5, d: 0.45 }, { f: B4, d: 0.3 }, { f: A4, d: 0.5 }
      ];
    } else if (titleNorm.includes('brahmastra')) {
      
      return [
        { f: D4, d: 0.35 }, { f: Fs4, d: 0.3 }, { f: A4, d: 0.45 }, { f: B4, d: 0.35 },
        { f: Cs5, d: 0.45 }, { f: B4, d: 0.3 }, { f: A4, d: 0.5 }
      ];
    } else if (titleNorm.includes('omshantiom')) {
      
      return [
        { f: D4, d: 0.3 }, { f: Fs4, d: 0.3 }, { f: A4, d: 0.35 }, { f: D5, d: 0.45 },
        { f: Cs5, d: 0.3 }, { f: B4, d: 0.3 }, { f: A4, d: 0.5 }
      ];
    } else if (titleNorm.includes('chakde')) {
      
      return [
        { f: E4, d: 0.25 }, { f: G4, d: 0.25 }, { f: A4, d: 0.35 }, { f: C5, d: 0.4 },
        { f: A4, d: 0.25 }, { f: G4, d: 0.25 }, { f: E4, d: 0.5 }
      ];
    } else if (titleNorm.includes('queen')) {
      
      return [
        { f: G4, d: 0.2 }, { f: A4, d: 0.2 }, { f: C5, d: 0.3 }, { f: D5, d: 0.35 },
        { f: C5, d: 0.2 }, { f: A4, d: 0.2 }, { f: G4, d: 0.45 }
      ];
    } else {
      
      return [
        { f: G4, d: 0.22 }, { f: C5, d: 0.22 }, { f: E5, d: 0.28 }, { f: G5, d: 0.38 },
        { f: E5, d: 0.22 }, { f: D5, d: 0.25 }, { f: C5, d: 0.48 }
      ];
    }
  }

  playSynthesizedMovieTune(movieTitle = '', maxSeconds = 20) {
    this.stopMovieTune();
    this.init();

    const pattern = this.getMovieMelodyPattern(movieTitle);
    if (!pattern || pattern.length === 0) return;

    let noteIndex = 0;
    this.isTuneActive = true;

    const playNext = () => {
      if (!this.isTuneActive) return;
      const note = pattern[noteIndex % pattern.length];
      this.playAcousticNote(note.f, note.d);
      noteIndex++;

      const delay = (note.d * 1000) + 40;
      this.stepTimer = setTimeout(playNext, delay);
    };

    playNext();

    this.tuneTimer = setTimeout(() => {
      this.stopMovieTune();
    }, maxSeconds * 1000);
  }

  stopMovieTune() {
    this.isTuneActive = false;
    if (this.tuneTimer) {
      clearTimeout(this.tuneTimer);
      this.tuneTimer = null;
    }
    if (this.stepTimer) {
      clearTimeout(this.stepTimer);
      this.stepTimer = null;
    }
    if (this.activeTrackAudio) {
      try {
        this.activeTrackAudio.pause();
        this.activeTrackAudio.currentTime = 0;
      } catch (e) {}
      this.activeTrackAudio = null;
    }
  }
}

