class DrawingCanvas {
  constructor(canvasId) {
    this.canvasId = canvasId;
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas ? this.canvas.getContext('2d') : null;
    this.isDrawing = false;
    this.isReadOnly = true;

    this.currentColor = '#ffffff';
    this.brushSize = 4;
    this.isEraser = false;

    this.lastX = 0;
    this.lastY = 0;
    this.history = []; 
    this.maxHistory = 20;

    this.onDrawAction = null; 

    if (this.canvas) {
      this.init();
    }
  }

  init() {
    this.bindEvents();
    
    setTimeout(() => this.resize(), 100);
    window.addEventListener('resize', () => {
      
      if (this.resizeTimeout) clearTimeout(this.resizeTimeout);
      this.resizeTimeout = setTimeout(() => this.resize(), 150);
    });
    window.addEventListener('orientationchange', () => {
      setTimeout(() => this.resize(), 200);
    });
  }

  resize() {
    if (!this.canvas) {
      this.canvas = document.getElementById(this.canvasId);
      if (this.canvas) this.ctx = this.canvas.getContext('2d');
      else return;
    }

    const container = this.canvas.parentElement;
    let width = container ? container.clientWidth : this.canvas.clientWidth;
    let height = container ? container.clientHeight : this.canvas.clientHeight;

    if (!width || width <= 0) width = 360;
    if (!height || height <= 0) height = 280;

    const dpr = window.devicePixelRatio || 1;

    
    let tempCanvas = null;
    if (this.canvas.width > 0 && this.canvas.height > 0) {
      tempCanvas = document.createElement('canvas');
      tempCanvas.width = this.canvas.width;
      tempCanvas.height = this.canvas.height;
      const tempCtx = tempCanvas.getContext('2d');
      tempCtx.drawImage(this.canvas, 0, 0);
    }

    this.canvas.width = Math.floor(width * dpr);
    this.canvas.height = Math.floor(height * dpr);

    this.canvas.style.width = width + 'px';
    this.canvas.style.height = height + 'px';

    this.ctx = this.canvas.getContext('2d');
    this.ctx.scale(dpr, dpr);
    this.ctx.lineCap = 'round';
    this.ctx.lineJoin = 'round';

    if (tempCanvas && tempCanvas.width > 0 && tempCanvas.height > 0) {
      this.ctx.drawImage(tempCanvas, 0, 0, width, height);
    } else {
      this.clearLocal(false);
    }
  }

  setReadOnly(readOnly) {
    this.isReadOnly = readOnly;
    if (!this.canvas) return;
    if (readOnly) {
      this.canvas.style.cursor = 'default';
      this.canvas.style.pointerEvents = 'none';
      this.canvas.style.touchAction = 'auto';
    } else {
      this.canvas.style.cursor = 'crosshair';
      this.canvas.style.pointerEvents = 'auto';
      this.canvas.style.touchAction = 'none';
      this.resize();
    }
  }

  getPointerPos(e) {
    const rect = this.canvas.getBoundingClientRect();
    let clientX = e.clientX;
    let clientY = e.clientY;

    if (e.touches && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    }

    const x = clientX - rect.left;
    const y = clientY - rect.top;
    const relX = rect.width > 0 ? x / rect.width : 0;
    const relY = rect.height > 0 ? y / rect.height : 0;

    return { x, y, relX, relY };
  }

  saveHistoryState() {
    if (!this.ctx || !this.canvas) return;
    try {
      if (this.history.length >= this.maxHistory) {
        this.history.shift();
      }
      this.history.push(this.ctx.getImageData(0, 0, this.canvas.width, this.canvas.height));
    } catch (e) {}
  }

  bindEvents() {
    if (!this.canvas) return;

    const startDrawing = (e) => {
      if (this.isReadOnly) return;
      if (e.cancelable) e.preventDefault();

      this.isDrawing = true;
      if (e.pointerId && this.canvas.setPointerCapture) {
        try { this.canvas.setPointerCapture(e.pointerId); } catch (err) {}
      }

      const pos = this.getPointerPos(e);
      this.lastX = pos.x;
      this.lastY = pos.y;
      this.saveHistoryState();

      const color = this.isEraser ? '#0f172a' : this.currentColor;
      this.drawDot(pos.x, pos.y, color, this.brushSize);

      if (this.onDrawAction) {
        this.onDrawAction({
          type: 'START',
          x: pos.relX,
          y: pos.relY,
          color: color,
          size: this.brushSize
        });
      }
    };

    const draw = (e) => {
      if (!this.isDrawing || this.isReadOnly) return;
      if (e.cancelable) e.preventDefault();

      const pos = this.getPointerPos(e);
      const color = this.isEraser ? '#0f172a' : this.currentColor;

      this.drawLine(
        this.lastX,
        this.lastY,
        pos.x,
        pos.y,
        color,
        this.brushSize
      );

      if (this.onDrawAction) {
        const rect = this.canvas.getBoundingClientRect();
        this.onDrawAction({
          type: 'MOVE',
          x1: rect.width > 0 ? this.lastX / rect.width : 0,
          y1: rect.height > 0 ? this.lastY / rect.height : 0,
          x2: pos.relX,
          y2: pos.relY,
          color: color,
          size: this.brushSize
        });
      }

      this.lastX = pos.x;
      this.lastY = pos.y;
    };

    const stopDrawing = (e) => {
      if (!this.isDrawing) return;
      this.isDrawing = false;
      if (e && e.pointerId && this.canvas.releasePointerCapture) {
        try { this.canvas.releasePointerCapture(e.pointerId); } catch (err) {}
      }
      if (this.onDrawAction) {
        this.onDrawAction({ type: 'END' });
      }
    };

    
    this.canvas.addEventListener('pointerdown', startDrawing);
    this.canvas.addEventListener('pointermove', draw);
    this.canvas.addEventListener('pointerup', stopDrawing);
    this.canvas.addEventListener('pointercancel', stopDrawing);
    this.canvas.addEventListener('pointerleave', stopDrawing);

    
    this.canvas.addEventListener('touchstart', startDrawing, { passive: false });
    this.canvas.addEventListener('touchmove', draw, { passive: false });
    this.canvas.addEventListener('touchend', stopDrawing);
  }

  drawDot(x, y, color, size) {
    if (!this.ctx) return;
    this.ctx.fillStyle = color;
    this.ctx.beginPath();
    this.ctx.arc(x, y, Math.max(1, size / 2), 0, Math.PI * 2);
    this.ctx.fill();
  }

  drawLine(x1, y1, x2, y2, color, size) {
    if (!this.ctx) return;
    this.ctx.strokeStyle = color;
    this.ctx.lineWidth = size;
    this.ctx.beginPath();
    this.ctx.moveTo(x1, y1);
    this.ctx.lineTo(x2, y2);
    this.ctx.stroke();
  }

  
  handleRemoteAction(action) {
    if (!this.ctx || !this.canvas) return;
    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width || this.canvas.clientWidth || 360;
    const height = rect.height || this.canvas.clientHeight || 280;

    if (action.type === 'START') {
      const x = action.x * width;
      const y = action.y * height;
      this.drawDot(x, y, action.color, action.size);
    } else if (action.type === 'MOVE') {
      const x1 = action.x1 * width;
      const y1 = action.y1 * height;
      const x2 = action.x2 * width;
      const y2 = action.y2 * height;
      this.drawLine(x1, y1, x2, y2, action.color, action.size);
    } else if (action.type === 'CLEAR') {
      this.clearLocal(false);
    } else if (action.type === 'UNDO') {
      this.undoLocal(false);
    }
  }

  clear() {
    this.clearLocal(true);
    if (this.onDrawAction) {
      this.onDrawAction({ type: 'CLEAR' });
    }
  }

  clearLocal(saveHistory = true) {
    if (!this.ctx || !this.canvas) return;
    if (saveHistory) this.saveHistoryState();
    const rect = this.canvas.getBoundingClientRect();
    const width = rect.width || this.canvas.clientWidth || 360;
    const height = rect.height || this.canvas.clientHeight || 280;
    this.ctx.fillStyle = '#0f172a'; 
    this.ctx.fillRect(0, 0, width, height);
  }

  undo() {
    this.undoLocal(true);
    if (this.onDrawAction) {
      this.onDrawAction({ type: 'UNDO' });
    }
  }

  undoLocal(saveCurrent = false) {
    if (!this.ctx || this.history.length === 0) return;
    const previousState = this.history.pop();
    if (previousState) {
      this.ctx.putImageData(previousState, 0, 0);
    }
  }

  setColor(color) {
    this.currentColor = color;
    this.isEraser = false;
  }

  setBrushSize(size) {
    this.brushSize = size;
  }

  setEraser(isEraser = true) {
    this.isEraser = isEraser;
  }
}


