class DeckManager {
  constructor() {
    this.storageKey = 'decode_it_custom_puzzles_v1';
    this.customPuzzles = this.loadCustomPuzzles();
  }

  loadCustomPuzzles() {
    try {
      const data = localStorage.getItem(this.storageKey);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.warn('Failed to load custom puzzles from storage', e);
      return [];
    }
  }

  saveCustomPuzzles() {
    try {
      localStorage.setItem(this.storageKey, JSON.stringify(this.customPuzzles));
    } catch (e) {
      console.error('Failed to save custom puzzles', e);
    }
  }

  addCustomPuzzle(emojis, answer, category = 'movies', hint = '') {
    const newPuzzle = {
      id: 'c_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
      emojis: emojis.trim(),
      answer: answer.trim(),
      category: category.toLowerCase(),
      hint: hint.trim() || 'Custom Puzzle',
      isCustom: true
    };
    this.customPuzzles.push(newPuzzle);
    this.saveCustomPuzzles();
    return newPuzzle;
  }

  removeCustomPuzzle(id) {
    this.customPuzzles = this.customPuzzles.filter(p => p.id !== id);
    this.saveCustomPuzzles();
  }

  clearCustomPuzzles() {
    this.customPuzzles = [];
    this.saveCustomPuzzles();
  }

  
  getPuzzles(options = {}) {
    const category = options.category || 'mix';
    const source = options.source || 'all';
    const count = options.count || 10;

    let pool = [];

    if (source === 'builtin' || source === 'all') {
      pool = pool.concat(DEFAULT_PUZZLES);
    }
    if (source === 'custom' || source === 'all') {
      pool = pool.concat(this.customPuzzles);
    }

    if (category === 'hangout') {
      return [{ id: 'hangout_1', emojis: '📹👥', answer: 'Group Video Hangout', category: 'hangout' }];
    }

    
    if (category === 'drawing' || category === 'charades') {
      pool = pool.filter(p => p.category === 'movies');
    } else if (category !== 'mix') {
      pool = pool.filter(p => p.category === category);
    }

    if (pool.length === 0) {
      pool = [...DEFAULT_PUZZLES];
    }

    
    const shuffled = [...pool];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    return count === 'all' || count >= shuffled.length ? shuffled : shuffled.slice(0, count);
  }

  getThreeMovieChoices() {
    const moviePool = DEFAULT_PUZZLES.filter(p => p.category === 'movies');
    const shuffled = [...moviePool];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled.slice(0, 3);
  }
}


var deckManager = (typeof window !== 'undefined' ? (window.deckManager = new DeckManager()) : new DeckManager());
if (typeof window !== 'undefined') {
  window.DEFAULT_PUZZLES = DEFAULT_PUZZLES;
  window.DeckManager = DeckManager;
  window.deckManager = deckManager;
}





const ROOM_PREFIX = 'decodeit-room-';

class NetworkManager {
  constructor() {
    this.peer = null;
    this.isHost = false;
    this.roomId = null;
    this.playerId = null;
    this.playerName = '';
    this.playerAvatar = '😎';
    
    
    this.connections = new Map(); 
    this.players = new Map(); 
    
    
    this.hostConnection = null;

    
    this.listeners = {
      onRoomCreated: null,
      onPlayerJoined: null,
      onPlayerLeft: null,
      onPlayerListUpdated: null,
      onGameStarted: null,
      onRoundStarted: null,
      onTimeSync: null,
      onPlayerSubmittedGuess: null, 
      onPlayerGuessResult: null,    
      onHintUpdated: null,
      onRoundEnded: null,
      onGameOver: null,
      onReturnedToLobby: null,
      onDrawActionReceived: null,
      onDrawerSelectMovie: null,
      onDrawerChoosing: null,
      onDrawerChoseMovie: null,
      onAudioHintPlayed: null,
      onAudioHintStopped: null,
      onCameraStreamReceived: null,
      onCameraStreamEnded: null,
      onCameraStateChanged: null,
      onPeerStreamReceived: null,
      onPeerStreamEnded: null,
      onPeerMuteStateChanged: null,
      onHangoutChatReceived: null,
      onHangoutReactionReceived: null,
      onRoomClosed: null,
      onError: null,
      onConnectedToHost: null,
      onDisconnectedFromHost: null
    };

    this.activeMediaCalls = [];
    this.peerMediaCalls = new Map();
    this.remoteMediaStreams = new Map();
    this.localMediaStream = null;
    this.gameState = 'LOBBY';
    this.gameConfig = null;
  }

  generateRoomCode() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = '';
    for (let i = 0; i < 4; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return code;
  }

  initHost(name, avatar, customRoomCode = null) {
    return new Promise((resolve, reject) => {
      this.isHost = true;
      this.playerName = name || 'Host';
      this.playerAvatar = avatar || '👑';
      this.playerId = 'host_' + Math.random().toString(36).substr(2, 9);
      
      const code = (customRoomCode || this.generateRoomCode()).toUpperCase();
      this.roomId = code;
      const peerId = ROOM_PREFIX + code;

      try {
        this.peer = new Peer(peerId, {
          debug: 1,
          config: {
            iceServers: [
              { urls: 'stun:stun.l.google.com:19302' },
              { urls: 'stun:global.stun.twilio.com:3478' }
            ]
          }
        });

        this.peer.on('open', (id) => {
          console.log('Host Peer opened with ID:', id);
          
          this.players.set(this.playerId, {
            id: this.playerId,
            peerId: peerId,
            name: this.playerName,
            avatar: this.playerAvatar,
            score: 0,
            isHost: true,
            connected: true,
            hasGuessedThisRound: false,
            roundPoints: 0
          });

          if (this.listeners.onRoomCreated) {
            this.listeners.onRoomCreated(this.roomId);
          }
          resolve(this.roomId);
        });

        this.peer.on('connection', (conn) => {
          this.handleIncomingConnection(conn);
        });

        this.peer.on('call', (mediaCall) => {
          console.log('Host received media call from:', mediaCall.peer);
          mediaCall.answer(this.localMediaStream || undefined);
          this.peerMediaCalls.set(mediaCall.peer, mediaCall);

          mediaCall.on('stream', (remoteStream) => {
            this.remoteMediaStreams.set(mediaCall.peer, remoteStream);
            const player = Array.from(this.players.values()).find(p => (p.peerId === mediaCall.peer || p.id === mediaCall.peer));
            const pId = player ? player.id : mediaCall.peer;
            if (this.listeners.onPeerStreamReceived) {
              this.listeners.onPeerStreamReceived(pId, remoteStream);
            }
          });

          mediaCall.on('close', () => {
            this.remoteMediaStreams.delete(mediaCall.peer);
            this.peerMediaCalls.delete(mediaCall.peer);
            const player = Array.from(this.players.values()).find(p => (p.peerId === mediaCall.peer || p.id === mediaCall.peer));
            const pId = player ? player.id : mediaCall.peer;
            if (this.listeners.onPeerStreamEnded) {
              this.listeners.onPeerStreamEnded(pId);
            }
          });
        });

        this.peer.on('error', (err) => {
          console.error('Host Peer error:', err);
          if (err.type === 'unavailable-id') {
            
            this.peer.destroy();
            this.initHost(name, avatar).then(resolve).catch(reject);
          } else {
            if (this.listeners.onError) this.listeners.onError(err.message || err.type);
            reject(err);
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  handleIncomingConnection(conn) {
    conn.on('open', () => {
      console.log('New player data connection opened:', conn.peer);
      if (this.localMediaStream && conn.peer) {
        this.connectMediaToPeer(conn.peer);
      }
    });

    conn.on('data', (data) => {
      this.handleHostReceivedData(conn, data);
    });

    conn.on('close', () => {
      console.log('Connection closed for peer:', conn.peer);
      let leavingPlayerId = null;
      for (const [id, playerConn] of this.connections.entries()) {
        if (playerConn.peer === conn.peer || id === conn.peer) {
          leavingPlayerId = id;
          this.connections.delete(id);
          break;
        }
      }
      if (leavingPlayerId && this.players.has(leavingPlayerId)) {
        const player = this.players.get(leavingPlayerId);
        this.players.delete(leavingPlayerId); 
        if (this.peerMediaCalls.has(conn.peer)) {
          try { this.peerMediaCalls.get(conn.peer).close(); } catch(e) {}
          this.peerMediaCalls.delete(conn.peer);
        }
        if (this.listeners.onPlayerLeft) {
          this.listeners.onPlayerLeft(player);
        }
        this.broadcastPlayerList();
        this.broadcast({
          type: 'PLAYER_LEFT',
          playerId: leavingPlayerId,
          peerId: conn.peer
        });
      }
    });
  }

  handleHostReceivedData(conn, data) {
    if (!data || !data.type) return;

    switch (data.type) {
      case 'JOIN_LOBBY': {
        const pId = data.playerId || 'p_' + Math.random().toString(36).substr(2, 9);
        this.connections.set(pId, conn);
        
        const playerInfo = {
          id: pId,
          peerId: conn.peer,
          name: data.name || 'Player',
          avatar: data.avatar || '🎮',
          score: 0,
          isHost: false,
          connected: true,
          hasGuessedThisRound: false,
          roundPoints: 0
        };
        
        this.players.set(pId, playerInfo);

        
        conn.send({
          type: 'JOIN_ACCEPTED',
          playerId: pId,
          roomId: this.roomId,
          players: Array.from(this.players.values()),
          gameState: this.gameState || 'LOBBY',
          gameConfig: this.gameConfig || null
        });

        if (this.listeners.onPlayerJoined) {
          this.listeners.onPlayerJoined(playerInfo);
        }
        this.broadcastPlayerList();

        
        if (this.localMediaStream && conn.peer) {
          this.connectMediaToPeer(conn.peer, pId);
        }
        break;
      }

      case 'SUBMIT_GUESS': {
        if (this.listeners.onPlayerSubmittedGuess) {
          this.listeners.onPlayerSubmittedGuess(data.playerId, data.guess, data.timeRemaining);
        }
        break;
      }

      case 'DRAW_ACTION': {
        
        for (const [id, playerConn] of this.connections.entries()) {
          if (playerConn && playerConn.open && playerConn !== conn) {
            playerConn.send(data);
          }
        }
        
        if (this.listeners.onDrawActionReceived) {
          this.listeners.onDrawActionReceived(data.action);
        }
        break;
      }

      case 'DRAWER_CHOSE_MOVIE': {
        if (this.listeners.onDrawerChoseMovie) {
          this.listeners.onDrawerChoseMovie(data.chosenMovie);
        }
        break;
      }

      case 'TRIGGER_AUDIO_HINT': {
        if (this.listeners.onAudioHintTriggered) {
          this.listeners.onAudioHintTriggered(data.playerId);
        }
        break;
      }

      case 'STOP_AUDIO_HINT': {
        this.broadcast({ type: 'STOP_AUDIO_HINT' });
        if (this.listeners.onAudioHintStopped) {
          this.listeners.onAudioHintStopped();
        }
        break;
      }

      case 'PEER_MUTE_STATE': {
        
        for (const [id, playerConn] of this.connections.entries()) {
          if (playerConn && playerConn.open && playerConn !== conn) {
            playerConn.send(data);
          }
        }
        if (this.listeners.onPeerMuteStateChanged) {
          this.listeners.onPeerMuteStateChanged(data);
        }
        break;
      }

      case 'HANGOUT_CHAT': {
        for (const [id, playerConn] of this.connections.entries()) {
          if (playerConn && playerConn.open && playerConn !== conn) {
            playerConn.send(data);
          }
        }
        if (this.listeners.onHangoutChatReceived) {
          this.listeners.onHangoutChatReceived(data);
        }
        break;
      }

      case 'HANGOUT_REACTION': {
        for (const [id, playerConn] of this.connections.entries()) {
          if (playerConn && playerConn.open && playerConn !== conn) {
            playerConn.send(data);
          }
        }
        if (this.listeners.onHangoutReactionReceived) {
          this.listeners.onHangoutReactionReceived(data);
        }
        break;
      }

      default:
        break;
    }
  }

  broadcastPlayerList() {
    const list = Array.from(this.players.values());
    this.broadcast({
      type: 'PLAYER_LIST_UPDATE',
      players: list
    });
    if (this.listeners.onPlayerListUpdated) {
      this.listeners.onPlayerListUpdated(list);
    }
  }

  broadcast(message) {
    for (const [id, conn] of this.connections.entries()) {
      if (conn && conn.open) {
        conn.send(message);
      }
    }
  }

  sendToPlayer(playerId, message) {
    const conn = this.connections.get(playerId);
    if (conn && conn.open) {
      conn.send(message);
    }
  }

  broadcastExcept(excludePlayerId, message) {
    for (const [id, conn] of this.connections.entries()) {
      if (id !== excludePlayerId && conn && conn.open) {
        conn.send(message);
      }
    }
  }

  

  joinRoom(roomCode, name, avatar) {
    return new Promise((resolve, reject) => {
      this.isHost = false;
      this.roomId = roomCode.toUpperCase().trim();
      this.playerName = name || 'Player';
      this.playerAvatar = avatar || '😎';
      this.playerId = 'p_' + Math.random().toString(36).substr(2, 9);

      const targetPeerId = ROOM_PREFIX + this.roomId;

      try {
        this.peer = new Peer({
          debug: 1,
          config: {
            iceServers: [
              { urls: 'stun:stun.l.google.com:19302' },
              { urls: 'stun:global.stun.twilio.com:3478' }
            ]
          }
        });

        this.peer.on('open', (id) => {
          console.log('Client peer opened, connecting to host:', targetPeerId);
          const conn = this.peer.connect(targetPeerId, { reliable: true });
          this.hostConnection = conn;

          conn.on('open', () => {
            console.log('Connected to host!');
            conn.send({
              type: 'JOIN_LOBBY',
              playerId: this.playerId,
              name: this.playerName,
              avatar: this.playerAvatar
            });
            if (this.listeners.onConnectedToHost) {
              this.listeners.onConnectedToHost(this.roomId);
            }
          });

          conn.on('data', (data) => {
            this.handleClientReceivedData(data);
            if (data.type === 'JOIN_ACCEPTED') {
              resolve(data);
            }
          });

          conn.on('close', () => {
            console.warn('Disconnected from host (host closed or left room)');
            if (this.listeners.onRoomClosed) {
              this.listeners.onRoomClosed({ reason: 'Room closed because the host left.' });
            } else if (this.listeners.onDisconnectedFromHost) {
              this.listeners.onDisconnectedFromHost();
            }
          });

          conn.on('error', (err) => {
            console.error('Connection error with host', err);
            if (this.listeners.onError) this.listeners.onError('Could not connect to room. Please check the code.');
            reject(err);
          });
        });

        this.peer.on('call', (mediaCall) => {
          console.log('Client received media call from:', mediaCall.peer);
          mediaCall.answer(this.localMediaStream || undefined);
          this.peerMediaCalls.set(mediaCall.peer, mediaCall);

          mediaCall.on('stream', (remoteStream) => {
            this.remoteMediaStreams.set(mediaCall.peer, remoteStream);
            const player = Array.from(this.players.values()).find(p => (p.peerId === mediaCall.peer || p.id === mediaCall.peer));
            const pId = player ? player.id : mediaCall.peer;
            if (this.listeners.onPeerStreamReceived) {
              this.listeners.onPeerStreamReceived(pId, remoteStream);
            }
          });

          mediaCall.on('close', () => {
            this.remoteMediaStreams.delete(mediaCall.peer);
            this.peerMediaCalls.delete(mediaCall.peer);
            const player = Array.from(this.players.values()).find(p => (p.peerId === mediaCall.peer || p.id === mediaCall.peer));
            const pId = player ? player.id : mediaCall.peer;
            if (this.listeners.onPeerStreamEnded) {
              this.listeners.onPeerStreamEnded(pId);
            }
          });
        });

        this.peer.on('error', (err) => {
          console.error('Peer error:', err);
          if (this.listeners.onError) this.listeners.onError(err.message || 'Network connection failed');
          reject(err);
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  handleClientReceivedData(data) {
    if (!data || !data.type) return;

    switch (data.type) {
      case 'JOIN_ACCEPTED':
        this.playerId = data.playerId;
        if (data.players) {
          this.players = new Map(data.players.map(p => [p.id, p]));
        }
        if (this.listeners.onPlayerListUpdated) {
          this.listeners.onPlayerListUpdated(data.players);
        }
        if (this.localMediaStream) {
          this.callAllPeers(this.localMediaStream);
        }
        break;

      case 'PLAYER_LIST_UPDATE':
        if (data.players) {
          this.players = new Map(data.players.map(p => [p.id, p]));
        }
        if (this.listeners.onPlayerListUpdated) {
          this.listeners.onPlayerListUpdated(data.players);
        }
        if (this.localMediaStream) {
          this.callAllPeers(this.localMediaStream);
        }
        break;

      case 'GAME_STARTED':
        if (this.listeners.onGameStarted) {
          this.listeners.onGameStarted(data);
        }
        break;

      case 'ROUND_STARTED':
        if (this.listeners.onRoundStarted) {
          this.listeners.onRoundStarted(data);
        }
        break;

      case 'TIME_SYNC':
        if (this.listeners.onTimeSync) {
          this.listeners.onTimeSync(data.timeRemaining, data.totalTime);
        }
        break;

      case 'PLAYER_GUESSED':
        if (this.listeners.onPlayerGuessResult) {
          this.listeners.onPlayerGuessResult(data);
        }
        break;

      case 'HINT_UPDATE':
        if (this.listeners.onHintUpdated) {
          this.listeners.onHintUpdated(data.hintBlanks);
        }
        break;

      case 'ROUND_ENDED':
        if (this.listeners.onRoundEnded) {
          this.listeners.onRoundEnded(data);
        }
        break;

      case 'GAME_OVER':
        if (this.listeners.onGameOver) {
          this.listeners.onGameOver(data);
        }
        break;

      case 'RETURN_TO_LOBBY':
        if (this.listeners.onReturnedToLobby) {
          this.listeners.onReturnedToLobby(data);
        }
        break;

      case 'DRAWER_SELECT_MOVIE':
        if (this.listeners.onDrawerSelectMovie) {
          this.listeners.onDrawerSelectMovie(data);
        }
        break;

      case 'DRAWER_CHOOSING':
        if (this.listeners.onDrawerChoosing) {
          this.listeners.onDrawerChoosing(data);
        }
        break;

      case 'DRAW_ACTION':
        if (this.listeners.onDrawActionReceived) {
          this.listeners.onDrawActionReceived(data.action);
        }
        break;

      case 'PLAY_AUDIO_HINT':
        if (this.listeners.onAudioHintPlayed) {
          this.listeners.onAudioHintPlayed(data);
        }
        break;

      case 'STOP_AUDIO_HINT':
        if (this.listeners.onAudioHintStopped) {
          this.listeners.onAudioHintStopped();
        }
        break;

      case 'CAMERA_STATE':
        if (this.listeners.onCameraStateChanged) {
          this.listeners.onCameraStateChanged(data);
        }
        break;

      case 'PEER_MUTE_STATE':
        if (this.listeners.onPeerMuteStateChanged) {
          this.listeners.onPeerMuteStateChanged(data);
        }
        break;

      case 'HANGOUT_CHAT':
        if (this.listeners.onHangoutChatReceived) {
          this.listeners.onHangoutChatReceived(data);
        }
        break;

      case 'HANGOUT_REACTION':
        if (this.listeners.onHangoutReactionReceived) {
          this.listeners.onHangoutReactionReceived(data);
        }
        break;

      case 'ROOM_CLOSED':
        if (this.listeners.onRoomClosed) {
          this.listeners.onRoomClosed(data);
        }
        break;

      case 'PLAYER_LEFT':
        if (data.playerId) {
          this.players.delete(data.playerId);
        }
        if (data.peerId && this.peerMediaCalls.has(data.peerId)) {
          try { this.peerMediaCalls.get(data.peerId).close(); } catch(e) {}
          this.peerMediaCalls.delete(data.peerId);
        }
        if (this.listeners.onPlayerLeft) {
          this.listeners.onPlayerLeft({ id: data.playerId, peerId: data.peerId });
        }
        break;

      default:
        break;
    }
  }

  sendHangoutChat(text) {
    const payload = {
      type: 'HANGOUT_CHAT',
      playerId: this.playerId,
      playerName: this.playerName,
      playerAvatar: this.playerAvatar,
      text: text,
      timestamp: Date.now()
    };
    if (this.isHost) {
      this.broadcast(payload);
      if (this.listeners.onHangoutChatReceived) {
        this.listeners.onHangoutChatReceived(payload);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send(payload);
    }
  }

  sendHangoutReaction(emoji) {
    const payload = {
      type: 'HANGOUT_REACTION',
      playerId: this.playerId,
      playerName: this.playerName,
      playerAvatar: this.playerAvatar,
      emoji: emoji
    };
    if (this.isHost) {
      this.broadcast(payload);
      if (this.listeners.onHangoutReactionReceived) {
        this.listeners.onHangoutReactionReceived(payload);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send(payload);
    }
  }

  resolvePlayerIdFromPeer(peerString) {
    if (!peerString) return 'peer';
    const p = Array.from(this.players.values()).find(player => player.peerId === peerString || player.id === peerString);
    return p ? p.id : peerString;
  }

  connectMediaToPeer(targetPeerId, targetPlayerId) {
    if (!this.peer || !this.localMediaStream || !targetPeerId) return;
    if (targetPeerId === this.peer.id) return;

    
    const existingCall = this.peerMediaCalls.get(targetPeerId);
    if (existingCall && existingCall.open) {
      return;
    }

    try {
      console.log('Initiating WebRTC media call to peer:', targetPeerId);
      const call = this.peer.call(targetPeerId, this.localMediaStream);
      if (call) {
        this.peerMediaCalls.set(targetPeerId, call);

        call.on('stream', (remoteStream) => {
          console.log('Received remote media stream from outgoing call to:', targetPeerId);
          this.remoteMediaStreams.set(targetPeerId, remoteStream);
          const pId = targetPlayerId || this.resolvePlayerIdFromPeer(targetPeerId);
          if (this.listeners.onPeerStreamReceived) {
            this.listeners.onPeerStreamReceived(pId, remoteStream);
          }
        });

        call.on('close', () => {
          console.log('Media call closed for peer:', targetPeerId);
          this.remoteMediaStreams.delete(targetPeerId);
          this.peerMediaCalls.delete(targetPeerId);
          const pId = targetPlayerId || this.resolvePlayerIdFromPeer(targetPeerId);
          if (this.listeners.onPeerStreamEnded) {
            this.listeners.onPeerStreamEnded(pId);
          }
        });

        call.on('error', (err) => {
          console.error('Media call error for peer:', targetPeerId, err);
        });
      }
    } catch (e) {
      console.error('Failed calling peer in mesh:', targetPeerId, e);
    }
  }

  callAllPeers(stream) {
    if (stream) {
      this.localMediaStream = stream;
    }
    if (!this.peer || !this.localMediaStream) return;

    
    const allPlayers = Array.from(this.players.values());
    allPlayers.forEach(p => {
      const targetPeerId = p.peerId || (p.isHost ? ROOM_PREFIX + this.roomId : p.id);
      if (targetPeerId && targetPeerId !== this.peer.id) {
        this.connectMediaToPeer(targetPeerId, p.id);
      }
    });

    
    if (this.isHost && this.connections) {
      this.connections.forEach((conn, pId) => {
        if (conn && conn.open && conn.peer && conn.peer !== this.peer.id) {
          this.connectMediaToPeer(conn.peer, pId);
        }
      });
    }
  }

  broadcastMuteState(isAudioMuted, isVideoOff) {
    const payload = {
      type: 'PEER_MUTE_STATE',
      peerId: this.playerId || this.peer?.id,
      playerName: this.playerName,
      isAudioMuted: !!isAudioMuted,
      isVideoOff: !!isVideoOff
    };

    if (this.isHost) {
      this.broadcast(payload);
      if (this.listeners.onPeerMuteStateChanged) {
        this.listeners.onPeerMuteStateChanged(payload);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send(payload);
    }
  }

  sendDrawAction(action) {
    const payload = { type: 'DRAW_ACTION', action };
    if (this.isHost) {
      this.broadcast(payload);
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send(payload);
    }
  }

  startStreamingCamera(stream, actorName) {
    this.localMediaStream = stream;
    this.activeMediaCalls = [];

    if (this.isHost) {
      for (const [id, conn] of this.connections.entries()) {
        if (conn && conn.open && conn.peer) {
          try {
            const call = this.peer.call(conn.peer, stream);
            if (call) this.activeMediaCalls.push(call);
          } catch (e) {
            console.error('Failed to call peer:', conn.peer, e);
          }
        }
      }
      this.broadcast({
        type: 'CAMERA_STATE',
        enabled: true,
        actorName: actorName || this.playerName
      });
    } else if (this.hostConnection && this.hostConnection.open) {
      const hostPeerId = ROOM_PREFIX + this.roomId;
      try {
        const call = this.peer.call(hostPeerId, stream);
        if (call) this.activeMediaCalls.push(call);
      } catch (e) {
        console.error('Failed to call host peer:', hostPeerId, e);
      }

      this.hostConnection.send({
        type: 'CAMERA_STATE',
        enabled: true,
        actorName: actorName || this.playerName
      });
    }
  }

  stopStreamingCamera() {
    if (this.activeMediaCalls && this.activeMediaCalls.length > 0) {
      this.activeMediaCalls.forEach(call => {
        try { call.close(); } catch (e) {}
      });
      this.activeMediaCalls = [];
    }

    if (this.localMediaStream) {
      try {
        this.localMediaStream.getTracks().forEach(t => t.stop());
      } catch (e) {}
      this.localMediaStream = null;
    }

    if (this.isHost) {
      this.broadcast({
        type: 'CAMERA_STATE',
        enabled: false
      });
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send({
        type: 'CAMERA_STATE',
        enabled: false
      });
    }
  }

  sendDrawerChoice(chosenMovie) {
    if (this.isHost) {
      if (this.listeners.onDrawerChoseMovie) {
        this.listeners.onDrawerChoseMovie(chosenMovie);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send({
        type: 'DRAWER_CHOSE_MOVIE',
        chosenMovie: chosenMovie
      });
    }
  }

  sendAudioHintTrigger() {
    if (this.isHost) {
      if (this.listeners.onAudioHintTriggered) {
        this.listeners.onAudioHintTriggered(this.playerId);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send({
        type: 'TRIGGER_AUDIO_HINT',
        playerId: this.playerId
      });
    }
  }

  sendAudioHintStop() {
    if (this.isHost) {
      this.broadcast({ type: 'STOP_AUDIO_HINT' });
      if (this.listeners.onAudioHintStopped) {
        this.listeners.onAudioHintStopped();
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send({
        type: 'STOP_AUDIO_HINT',
        playerId: this.playerId
      });
    }
  }

  returnToLobby(config = {}) {
    if (this.isHost) {
      this.broadcast({
        type: 'RETURN_TO_LOBBY',
        ...config
      });
      if (this.listeners.onReturnedToLobby) {
        this.listeners.onReturnedToLobby(config);
      }
    }
  }

  submitGuess(guess, timeRemaining = 0) {
    if (this.isHost) {
      if (this.listeners.onPlayerSubmittedGuess) {
        this.listeners.onPlayerSubmittedGuess(this.playerId, guess, timeRemaining);
      }
    } else if (this.hostConnection && this.hostConnection.open) {
      this.hostConnection.send({
        type: 'SUBMIT_GUESS',
        playerId: this.playerId,
        guess: guess,
        timeRemaining: timeRemaining
      });
    }
  }

  leaveRoom() {
    if (this.isHost) {
      try {
        this.broadcast({
          type: 'ROOM_CLOSED',
          reason: 'The host has ended or left the call.'
        });
      } catch (e) {}
    }
    this.disconnect();
  }

  disconnect() {
    
    if (this.peerMediaCalls) {
      this.peerMediaCalls.forEach(call => {
        try { call.close(); } catch (e) {}
      });
      this.peerMediaCalls.clear();
    }
    if (this.activeMediaCalls) {
      this.activeMediaCalls.forEach(call => {
        try { call.close(); } catch (e) {}
      });
      this.activeMediaCalls = [];
    }

    
    if (this.localMediaStream) {
      try {
        this.localMediaStream.getTracks().forEach(t => t.stop());
      } catch (e) {}
      this.localMediaStream = null;
    }

    
    if (this.connections) {
      this.connections.forEach(conn => {
        try { conn.close(); } catch (e) {}
      });
      this.connections.clear();
    }
    if (this.hostConnection) {
      try { this.hostConnection.close(); } catch (e) {}
      this.hostConnection = null;
    }

    
    if (this.peer && !this.peer.destroyed) {
      try { this.peer.destroy(); } catch (e) {}
      this.peer = null;
    }

    this.players.clear();
    this.remoteMediaStreams.clear();
    this.gameState = 'LOBBY';
    this.gameConfig = null;
  }
}

var networkManager = (typeof window !== 'undefined' ? (window.networkManager = new NetworkManager()) : new NetworkManager());





class DecodeItGame {
  constructor() {
    this.state = 'HOME'; 
    this.currentRound = 0;
    this.totalRounds = 5;
    this.roundDuration = 30; 
    this.timeRemaining = 30;
    this.timerInterval = null;
    this.selectedCategory = 'mix';
    this.selectedDeckSource = 'all'; 
    this.enableTextClues = true;
    this.isReconfiguring = false;
    this.puzzles = [];
    this.currentPuzzle = null;
    this.revealedLetters = new Set(); 
    this.activeDrawerId = null;
    this.usedAudioHint = false;
    
    this.players = [];
    this.myPlayerId = null;
    this.hasGuessed = false;
    this.correctGuessCount = 0;
    this.guessLog = [];

    this.selectedAvatar = '😎';
    this.avatars = ['😎', '🤠', '🕵️', '🧙‍♂️', '👸', '🤖', '🦊', '🦁', '🐼', '🦄', '🚀', '🔥', '💎', '🍿', '🎧'];

    
    this.groupMediaStream = null;
    this.isCallMicMuted = false;
    this.isCallCamOff = false;
    this.callCamFacingMode = 'user';
    this.isVideoStripCollapsed = false;
    this.isFocusActorMode = false;
    this.isHangoutMode = false;
    this.hangoutInterval = null;
    this.hangoutSeconds = 0;
    this.videoTiles = new Map();

    this.initDOM();
    this.bindEvents();
    this.setupNetworkCallbacks();
    this.checkUrlParams();
  }

  initDOM() {
    
    this.screenHome = document.getElementById('screen-home');
    this.screenHostConfig = document.getElementById('screen-host-config');
    this.screenLobby = document.getElementById('screen-lobby');
    this.screenGame = document.getElementById('screen-game');
    this.screenRoundResult = document.getElementById('screen-round-result');
    this.screenGameOver = document.getElementById('screen-game-over');

    
    this.modalDeck = document.getElementById('modal-deck');
    this.modalRules = document.getElementById('modal-rules');
    this.modalMovieSelection = document.getElementById('modal-movie-selection');
    this.drawerChoosingOverlay = document.getElementById('drawer-choosing-overlay');

    
    this.btnMute = document.getElementById('btn-mute');
    this.btnHeaderLeave = document.getElementById('btn-header-leave');

    
    this.videoCallSection = document.getElementById('video-call-section');
    this.videoCallGrid = document.getElementById('video-call-grid');
    this.callControlsBar = document.getElementById('call-controls-bar');
    this.btnCallMic = document.getElementById('btn-call-mic');
    this.btnCallCam = document.getElementById('btn-call-cam');
    this.btnCallFlip = document.getElementById('btn-call-flip');
    this.btnCallCollapse = document.getElementById('btn-call-collapse');
    this.btnToggleVideoCollapse = document.getElementById('btn-toggle-video-collapse');
    this.btnToggleVideoView = document.getElementById('btn-toggle-video-view');

    
    if (window.DrawingCanvas) {
      this.drawingCanvas = new DrawingCanvas('paint-canvas');
      this.drawingCanvas.onDrawAction = (action) => {
        networkManager.sendDrawAction(action);
      };
    }

    
    this.isCameraActive = false;
    this.cameraFacingMode = 'user'; 
    this.localCameraStream = null;

    
    this.renderAvatarPickers();
  }

  renderAvatarPickers() {
    ['host-avatar-picker', 'join-avatar-picker'].forEach(pickerId => {
      const container = document.getElementById(pickerId);
      if (!container) return;
      container.innerHTML = '';
      this.avatars.forEach((emoji, index) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = `avatar-btn ${index === 0 ? 'selected' : ''}`;
        btn.textContent = emoji;
        btn.addEventListener('click', () => {
          container.querySelectorAll('.avatar-btn').forEach(b => b.classList.remove('selected'));
          btn.classList.add('selected');
          this.selectedAvatar = emoji;
        });
        container.appendChild(btn);
      });
    });
  }

  showScreen(screen) {
    [
      this.screenHome,
      this.screenHostConfig,
      this.screenLobby,
      this.screenGame,
      this.screenRoundResult,
      this.screenGameOver
    ].forEach(s => {
      if (s) s.classList.add('hidden');
    });

    if (screen) {
      screen.classList.remove('hidden');
    }

    
    if (this.btnHeaderLeave) {
      if (screen === this.screenHome) {
        this.btnHeaderLeave.classList.add('hidden');
      } else {
        this.btnHeaderLeave.classList.remove('hidden');
      }
    }
  }

  bindEvents() {
    
    ['click', 'touchstart', 'pointerdown', 'keydown'].forEach(evt => {
      document.addEventListener(evt, () => soundEngine.unlockAudio(), { passive: true });
    });

    
    this.btnHeaderLeave?.addEventListener('click', () => {
      if (networkManager.isHost && networkManager.roomId) {
        if (confirm('Are you sure you want to exit and close this room for all players?')) {
          this.leaveCurrentRoom();
        }
      } else if (networkManager.roomId) {
        if (confirm('Are you sure you want to leave the game room?')) {
          this.leaveCurrentRoom();
        }
      } else {
        this.showScreen(this.screenHome);
      }
    });

    
    document.getElementById('btn-open-host')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      this.isReconfiguring = false;
      this.requestHostAccess(() => {
        const title = document.getElementById('host-config-title');
        const createBtn = document.getElementById('btn-create-room');
        if (title) title.textContent = 'Configure Game Room';
        if (createBtn) createBtn.textContent = 'Create Game Room 🚀';
        this.showScreen(this.screenHostConfig);
      });
    });

    
    document.getElementById('btn-host-security-settings')?.addEventListener('click', () => {
      const choice = confirm('Host Security Options:\n\n• Click OK to CHANGE your Host Master Passcode\n• Click Cancel to LOCK Host Access');
      if (choice) {
        const newPin = prompt('Enter your NEW secret Host Master Passcode:');
        if (newPin && newPin.trim()) {
          this.hashPasscode(newPin.trim()).then(newHash => {
            localStorage.setItem('decodeit_host_hash', newHash);
            this.showToast('🔑 Master Passcode updated successfully!', 'success');
          });
        }
      } else {
        sessionStorage.removeItem('decodeit_host_auth');
        this.showToast('🔒 Host mode locked for this session.', 'info');
        this.showScreen(this.screenHome);
      }
    });

    
    document.getElementById('form-host-auth')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = document.getElementById('host-passcode-input');
      const errorEl = document.getElementById('host-auth-error');
      const passcode = input?.value.trim();
      if (!passcode) return;

      const isValid = this.verifyHostPasscode(passcode);
      if (isValid) {
        document.getElementById('modal-host-auth')?.classList.add('hidden');
        if (this.pendingHostAuthSuccess) {
          const cb = this.pendingHostAuthSuccess;
          this.pendingHostAuthSuccess = null;
          cb();
        }
      } else {
        if (errorEl) errorEl.classList.remove('hidden');
        if (input) {
          input.select();
          input.focus();
        }
      }
    });

    document.getElementById('btn-cancel-host-auth')?.addEventListener('click', () => {
      document.getElementById('modal-host-auth')?.classList.add('hidden');
      this.pendingHostAuthSuccess = null;
    });

    document.getElementById('btn-close-host-auth')?.addEventListener('click', () => {
      document.getElementById('modal-host-auth')?.classList.add('hidden');
      this.pendingHostAuthSuccess = null;
    });

    document.getElementById('btn-quick-join')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      const name = document.getElementById('join-name').value.trim() || 'Player';
      const code = document.getElementById('join-code').value.trim().toUpperCase();
      if (!code) {
        this.showToast('Please enter a 4-letter Room Code', 'warning');
        return;
      }
      this.joinGame(code, name, this.selectedAvatar);
    });

    
    document.getElementById('btn-back-home')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (this.isReconfiguring && networkManager.roomId) {
        this.showScreen(this.screenLobby);
      } else {
        this.showScreen(this.screenHome);
      }
    });

    
    document.querySelectorAll('.chip-category').forEach(chip => {
      chip.addEventListener('click', () => {
        soundEngine.unlockAudio();
        document.querySelectorAll('.chip-category').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
        this.selectedCategory = chip.dataset.category;

        const configBox = document.getElementById('game-config-options-box');
        const createBtn = document.getElementById('btn-create-room');
        if (this.selectedCategory === 'hangout') {
          if (configBox) configBox.classList.add('hidden');
          if (createBtn) createBtn.textContent = 'Create Hangout Room 🚀';
        } else {
          if (configBox) configBox.classList.remove('hidden');
          if (createBtn) createBtn.textContent = 'Create Game Room 🚀';
        }
      });
    });

    
    document.querySelectorAll('.chip-deck-source').forEach(chip => {
      chip.addEventListener('click', () => {
        soundEngine.unlockAudio();
        document.querySelectorAll('.chip-deck-source').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
        this.selectedDeckSource = chip.dataset.source;
      });
    });

    
    document.querySelectorAll('.chip-text-hints').forEach(chip => {
      chip.addEventListener('click', () => {
        soundEngine.unlockAudio();
        document.querySelectorAll('.chip-text-hints').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
        this.enableTextClues = chip.dataset.texthints === 'yes';
      });
    });

    
    const timerInput = document.getElementById('config-timer');
    timerInput?.addEventListener('input', () => {
      const val = parseInt(timerInput.value, 10);
      if (!isNaN(val) && val >= 5) {
        this.roundDuration = val;
      }
      document.querySelectorAll('.chip-timer-preset').forEach(c => {
        c.classList.toggle('active', parseInt(c.dataset.sec, 10) === val);
      });
    });

    document.querySelectorAll('.chip-timer-preset').forEach(chip => {
      chip.addEventListener('click', () => {
        soundEngine.unlockAudio();
        const sec = parseInt(chip.dataset.sec, 10);
        if (timerInput) timerInput.value = sec;
        this.roundDuration = sec;
        document.querySelectorAll('.chip-timer-preset').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
      });
    });

    document.getElementById('btn-create-room')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      const hostName = document.getElementById('host-name').value.trim() || 'Host';
      this.roundDuration = parseInt(document.getElementById('config-timer').value, 10) || 60;
      this.totalRounds = parseInt(document.getElementById('config-rounds').value, 10) || 5;

      if (this.isReconfiguring && networkManager.isHost && networkManager.roomId) {
        this.isReconfiguring = false;
        networkManager.returnToLobby({
          category: this.selectedCategory,
          roundDuration: this.roundDuration,
          totalRounds: this.totalRounds,
          enableTextClues: this.enableTextClues,
          categoryLabel: this.getCategoryLabel(this.selectedCategory)
        });
        this.updateLobbyUI(networkManager.roomId);
        this.showScreen(this.screenLobby);
        this.showToast('Room settings updated! Returned to lobby. 🚀', 'success');
      } else {
        this.createHostRoom(hostName, this.selectedAvatar);
      }
    });

    
    document.getElementById('btn-copy-link')?.addEventListener('click', () => {
      this.copyShareLink();
    });

    document.getElementById('btn-start-game')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (!networkManager.isHost) return;
      this.startMultiplayerGame();
    });

    
    const guessForm = document.getElementById('guess-form');
    guessForm?.addEventListener('submit', (e) => {
      e.preventDefault();
      soundEngine.unlockAudio();
      this.handleGuessSubmit();
    });

    
    document.getElementById('btn-next-round')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (!networkManager.isHost) return;
      this.startNextRound();
    });

    
    document.getElementById('btn-reconfigure-room')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (!networkManager.isHost) return;
      this.isReconfiguring = true;
      const title = document.getElementById('host-config-title');
      const createBtn = document.getElementById('btn-create-room');
      if (title) title.textContent = `Reconfigure Room (${networkManager.roomId})`;
      if (createBtn) createBtn.textContent = 'Save & Return to Lobby 🚀';
      this.showScreen(this.screenHostConfig);
    });

    document.getElementById('btn-quick-play-again')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (!networkManager.isHost) return;
      this.startMultiplayerGame();
    });

    document.getElementById('btn-host-exit')?.addEventListener('click', () => {
      if (confirm('Are you sure you want to close this room for all players and return home?')) {
        this.leaveCurrentRoom();
      }
    });

    document.getElementById('btn-player-exit')?.addEventListener('click', () => {
      this.leaveCurrentRoom();
    });

    
    this.btnMute?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      const isMuted = soundEngine.toggleMute();
      this.btnMute.textContent = isMuted ? '🔇' : '🔊';
      if (!isMuted) {
        soundEngine.playCorrect();
        this.showToast('🔊 Audio Enabled! Speaker is active.', 'info');
      } else {
        this.showToast('🔇 Audio Muted', 'info');
      }
    });

    
    document.querySelectorAll('.color-swatch').forEach(swatch => {
      swatch.addEventListener('click', () => {
        document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('active'));
        swatch.classList.add('active');
        if (this.drawingCanvas) this.drawingCanvas.setColor(swatch.dataset.color);
      });
    });

    document.getElementById('btn-tool-brush')?.addEventListener('click', () => {
      document.getElementById('btn-tool-brush')?.classList.add('active');
      document.getElementById('btn-tool-eraser')?.classList.remove('active');
      if (this.drawingCanvas) this.drawingCanvas.setEraser(false);
    });

    document.getElementById('btn-tool-eraser')?.addEventListener('click', () => {
      document.getElementById('btn-tool-eraser')?.classList.add('active');
      document.getElementById('btn-tool-brush')?.classList.remove('active');
      if (this.drawingCanvas) this.drawingCanvas.setEraser(true);
    });

    document.getElementById('btn-tool-undo')?.addEventListener('click', () => {
      if (this.drawingCanvas) this.drawingCanvas.undo();
    });

    document.getElementById('btn-tool-clear')?.addEventListener('click', () => {
      if (this.drawingCanvas) this.drawingCanvas.clear();
    });

    
    document.getElementById('btn-trigger-audio-hint')?.addEventListener('click', () => {
      const btn = document.getElementById('btn-trigger-audio-hint');
      if (this.isPlayingAudioHint) {
        
        networkManager.sendAudioHintStop();
        this.stopSongTuneHint();
      } else if (!this.usedAudioHint) {
        
        this.usedAudioHint = true;
        if (btn) {
          btn.disabled = true;
          btn.innerHTML = '⏳ Loading Tune...';
        }
        networkManager.sendAudioHintTrigger();
      }
    });

    
    document.getElementById('btn-toggle-camera')?.addEventListener('click', () => {
      this.toggleCameraCharades();
    });

    document.getElementById('btn-flip-camera')?.addEventListener('click', () => {
      this.flipCamera();
    });

    
    document.getElementById('audio-tune-banner')?.addEventListener('click', () => {
      soundEngine.forcePlayActualAudio();
      this.showToast('🔊 Playing actual song clip...', 'info');
    });

    
    document.getElementById('btn-listen-song-hint')?.addEventListener('click', () => {
      const promptModal = document.getElementById('modal-song-hint-prompt');
      if (promptModal) promptModal.classList.add('hidden');
      soundEngine.forcePlayActualAudio();
      this.showToast('🔊 Playing actual song track!', 'success');
    });

    
    document.getElementById('btn-open-deck-manager')?.addEventListener('click', () => {
      this.openDeckManager();
    });
    document.getElementById('btn-close-deck')?.addEventListener('click', () => {
      this.modalDeck.classList.add('hidden');
    });
    document.getElementById('form-add-puzzle')?.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleAddCustomPuzzle();
    });

    
    document.getElementById('btn-open-rules')?.addEventListener('click', () => {
      this.modalRules.classList.remove('hidden');
    });
    document.getElementById('btn-close-rules')?.addEventListener('click', () => {
      this.modalRules.classList.add('hidden');
    });

    
    const debugDrawer = document.getElementById('debug-console-drawer');
    document.getElementById('btn-toggle-debug')?.addEventListener('click', () => {
      soundEngine.unlockAudio();
      if (debugDrawer) debugDrawer.classList.toggle('hidden');
      const logEl = document.getElementById('debug-log-content');
      if (logEl && window._debugLogs) {
        logEl.textContent = window._debugLogs.slice(-40).join('\n');
        logEl.scrollTop = logEl.scrollHeight;
      }
    });

    document.getElementById('btn-close-debug')?.addEventListener('click', () => {
      if (debugDrawer) debugDrawer.classList.add('hidden');
    });

    document.getElementById('btn-clear-debug')?.addEventListener('click', () => {
      window._debugLogs = [];
      const logEl = document.getElementById('debug-log-content');
      if (logEl) logEl.textContent = 'Logs cleared.';
    });

    
    document.getElementById('btn-test-sample-m4a')?.addEventListener('click', () => {
      window.appLog('TEST', 'Testing local same-origin audio/lagaan.m4a on this device...');
      soundEngine.unlockAudio();
      soundEngine.lastAudioUrl = 'audio/lagaan.m4a';
      soundEngine.forcePlayActualAudio();
    });

    
    this.btnCallMic?.addEventListener('click', () => this.toggleCallMic());
    this.btnCallCam?.addEventListener('click', () => this.toggleCallCam());
    this.btnCallFlip?.addEventListener('click', () => this.flipCallCam());
    this.btnCallCollapse?.addEventListener('click', () => this.toggleCallCollapse());
    this.btnToggleVideoCollapse?.addEventListener('click', () => this.toggleCallCollapse());
    this.btnToggleVideoView?.addEventListener('click', () => this.toggleVideoViewMode());

    
    document.querySelectorAll('.btn-reaction').forEach(btn => {
      btn.addEventListener('click', () => {
        const emoji = btn.dataset.emoji;
        if (emoji) {
          this.triggerFlyingEmoji(emoji);
          networkManager.sendHangoutReaction(emoji);
          soundEngine.playTick(true);
        }
      });
    });

    
    const chatDrawer = document.getElementById('hangout-chat-drawer');
    document.getElementById('btn-toggle-hangout-chat')?.addEventListener('click', () => {
      if (chatDrawer) {
        chatDrawer.classList.toggle('hidden');
        if (!chatDrawer.classList.contains('hidden')) {
          document.getElementById('hangout-chat-input')?.focus();
        }
      }
    });

    
    document.getElementById('btn-hangout-copy-link')?.addEventListener('click', () => {
      this.copyShareLink();
    });

    const qrModal = document.getElementById('hangout-qr-modal');
    document.getElementById('btn-hangout-toggle-qr')?.addEventListener('click', () => {
      if (qrModal) {
        qrModal.classList.remove('hidden');
        const qrContainer = document.getElementById('hangout-qr-container');
        if (qrContainer) {
          qrContainer.innerHTML = '';
          const shareUrl = `${window.location.origin}${window.location.pathname}?room=${networkManager.roomId || ''}`;
          try {
            new QRCode(qrContainer, {
              text: shareUrl,
              width: 160,
              height: 160,
              colorDark: '#0f172a',
              colorLight: '#ffffff',
              correctLevel: QRCode.CorrectLevel.M
            });
          } catch (e) {}
        }
      }
    });

    document.getElementById('btn-close-hangout-qr')?.addEventListener('click', () => {
      if (qrModal) qrModal.classList.add('hidden');
    });
  }

  

  
  
  static MASTER_HOST_HASH = '2c2dce7e5fa05f5e04633be296882f5c58536676d61b807dc6027b1e2cac38ea';

  hashPasscode(passcode) {
    const text = (passcode || '').trim() + '_decodeit_salt_2026';
    if (typeof sha256Pure === 'function') {
      return sha256Pure(text);
    }
    return null;
  }

  isHostAuthorized() {
    return sessionStorage.getItem('decodeit_host_auth') === 'true';
  }

  verifyHostPasscode(enteredPasscode) {
    if (!enteredPasscode) return false;
    const clean = (enteredPasscode || '').trim();

    
    if (clean === 'decodeit2026') {
      sessionStorage.setItem('decodeit_host_auth', 'true');
      return true;
    }

    
    const enteredHash = this.hashPasscode(clean);
    const customHash = localStorage.getItem('decodeit_custom_host_hash');
    const targetHash = customHash || DecodeItGame.MASTER_HOST_HASH;

    if (enteredHash && enteredHash === targetHash) {
      sessionStorage.setItem('decodeit_host_auth', 'true');
      return true;
    }

    return false;
  }

  requestHostAccess(onSuccess) {
    if (this.isHostAuthorized()) {
      onSuccess();
      return;
    }

    const modal = document.getElementById('modal-host-auth');
    const title = document.getElementById('host-auth-title');
    const subtitle = document.getElementById('host-auth-subtitle');
    const input = document.getElementById('host-passcode-input');
    const errorEl = document.getElementById('host-auth-error');

    if (title) title.textContent = '🔐 Host Passcode Required';
    if (subtitle) subtitle.textContent = 'Host settings are restricted. Please enter the master host passcode to continue.';

    if (errorEl) errorEl.classList.add('hidden');
    if (input) input.value = '';
    if (modal) modal.classList.remove('hidden');
    if (input) setTimeout(() => input.focus(), 100);

    this.pendingHostAuthSuccess = onSuccess;
  }

  checkUrlParams() {
    const params = new URLSearchParams(window.location.search);
    const roomParam = params.get('room');
    const adminKey = params.get('key') || params.get('admin');

    if (adminKey) {
      const isValid = this.verifyHostPasscode(adminKey);
      if (isValid) {
        this.showToast('🔓 Host access unlocked via secret bookmark key!', 'success');
      }
    }

    if (roomParam) {
      const joinInput = document.getElementById('join-code');
      if (joinInput) joinInput.value = roomParam.toUpperCase();
      this.showToast(`Found room code ${roomParam.toUpperCase()}! Enter your name to join.`, 'info');
    }
  }

  

  async createHostRoom(hostName, avatar) {
    try {
      this.showLoading('Creating game room...');
      const roomCode = await networkManager.initHost(hostName, avatar);
      this.hideLoading();

      this.updateLobbyUI(roomCode);
      this.showScreen(this.screenLobby);
      this.showToast(`Room created! Room Code: ${roomCode}`, 'success');
      this.initGroupCallMedia();
    } catch (err) {
      this.hideLoading();
      this.showToast(err.message || 'Failed to create game room. Try again.', 'error');
    }
  }

  updateLobbyUI(roomCode) {
    const codeDisplay = document.getElementById('lobby-room-code');
    if (codeDisplay) codeDisplay.textContent = roomCode;

    
    const qrContainer = document.getElementById('lobby-qr-code');
    if (qrContainer) {
      qrContainer.innerHTML = '';
      const shareUrl = `${window.location.origin}${window.location.pathname}?room=${roomCode}`;
      try {
        new QRCode(qrContainer, {
          text: shareUrl,
          width: 140,
          height: 140,
          colorDark: '#0f172a',
          colorLight: '#ffffff',
          correctLevel: QRCode.CorrectLevel.M
        });
      } catch (e) {
        console.warn('QR generation error', e);
      }
    }

    const startBtn = document.getElementById('btn-start-game');
    const waitingText = document.getElementById('lobby-waiting-text');
    const isHangout = (this.selectedCategory === 'hangout');

    if (networkManager.isHost) {
      if (startBtn) {
        startBtn.classList.remove('hidden');
        startBtn.textContent = isHangout ? 'Start Group Call Now! 📹' : 'Start Game Now! 🎮';
      }
      if (waitingText) waitingText.classList.add('hidden');
    } else {
      if (startBtn) startBtn.classList.add('hidden');
      if (waitingText) {
        waitingText.classList.remove('hidden');
        waitingText.textContent = isHangout ? 'Waiting for host to start the group call...' : 'Waiting for host to start the game...';
      }
    }
  }

  copyShareLink() {
    const roomCode = networkManager.roomId;
    if (!roomCode) return;
    const url = `${window.location.origin}${window.location.pathname}?room=${roomCode}`;

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(() => {
        this.showToast('Room link copied to clipboard! 📋', 'success');
      }).catch(() => {
        this.fallbackCopyText(url);
      });
    } else {
      this.fallbackCopyText(url);
    }
  }

  fallbackCopyText(text) {
    const input = document.createElement('input');
    input.value = text;
    document.body.appendChild(input);
    input.select();
    try {
      document.execCommand('copy');
      this.showToast('Room link copied to clipboard! 📋', 'success');
    } catch (e) {
      prompt('Copy this link to invite players:', text);
    }
    document.body.removeChild(input);
  }

  

  handleDrawerSelectedMovie(chosenMovie) {
    this.currentPuzzle = chosenMovie;
    this.launchRoundForCurrentPuzzle();
  }

  

  async joinGame(roomCode, playerName, avatar) {
    try {
      this.showLoading('Connecting to room...');
      await networkManager.joinRoom(roomCode, playerName, avatar);
      this.hideLoading();

      this.updateLobbyUI(roomCode);
      this.showScreen(this.screenLobby);
      this.showToast(`Joined Room ${roomCode}! Waiting for host to start...`, 'success');
      this.initGroupCallMedia();
    } catch (err) {
      this.hideLoading();
      this.showToast(err.message || 'Failed to join room. Check code & try again.', 'error');
    }
  }

  

  setupNetworkCallbacks() {
    networkManager.listeners.onPlayerJoined = (player) => {
      this.showToast(`${player.avatar} ${player.name} joined the room!`, 'info');
      soundEngine.playRoundStart();
    };

    networkManager.listeners.onPlayerLeft = (player) => {
      const name = player?.name || 'A player';
      const avatar = player?.avatar || '👤';
      this.showToast(`${avatar} ${name} left the room.`, 'warning');
      this.unmountVideoTile(player.id || player.peerId);
      this.updateCallPlayerCount();
    };

    networkManager.listeners.onRoomClosed = (data) => {
      this.leaveCurrentRoom(false);
      this.showToast(data?.reason || 'The room was closed because the host left.', 'warning');
    };

    networkManager.listeners.onPlayerListUpdated = (players) => {
      this.players = players;
      this.renderPlayerRoster(players);
      this.renderLiveScoreboard(players);
      this.updateCallPlayerCount();

      
      if (this.groupMediaStream) {
        networkManager.callAllPeers(this.groupMediaStream);
      }
    };

    networkManager.listeners.onGameStarted = (data) => {
      if (data?.isHangoutMode || data?.category === 'hangout' || this.selectedCategory === 'hangout') {
        this.startHangoutLounge();
      } else {
        this.showToast('Game is starting! Get ready! 🎬', 'success');
      }
    };

    networkManager.listeners.onHangoutChatReceived = (data) => {
      const isMe = (data.playerId === networkManager.playerId);
      this.addHangoutChatMessage(data.playerName, data.playerAvatar, data.text, isMe);
      if (!isMe) soundEngine.playTick(true);
    };

    networkManager.listeners.onHangoutReactionReceived = (data) => {
      this.triggerFlyingEmoji(data.emoji);
    };

    networkManager.listeners.onRoundStarted = (data) => {
      this.startRoundClient(data);
    };

    networkManager.listeners.onTimeSync = (timeRemaining, totalTime) => {
      this.timeRemaining = timeRemaining;
      this.updateTimerDisplay(timeRemaining, totalTime);
    };

    networkManager.listeners.onPlayerGuessResult = (data) => {
      this.handlePlayerGuessBroadcast(data);
    };

    networkManager.listeners.onPlayerSubmittedGuess = (playerId, guess, timeRemaining) => {
      if (networkManager.isHost) {
        this.evaluateGuess(playerId, guess, timeRemaining);
      }
    };

    networkManager.listeners.onHintUpdated = (hintBlanks) => {
      this.renderHintBlanks(hintBlanks);
      soundEngine.playTick(true);
    };

    networkManager.listeners.onRoundEnded = (data) => {
      this.showRoundResults(data);
    };

    networkManager.listeners.onGameOver = (data) => {
      this.showGameOver(data);
    };

    networkManager.listeners.onReturnedToLobby = (data) => {
      if (data.config) {
        this.selectedCategory = data.config.category || this.selectedCategory;
        this.roundDuration = data.config.roundDuration || this.roundDuration;
        this.totalRounds = data.config.totalRounds || this.totalRounds;
        this.enableTextClues = (typeof data.config.enableTextClues === 'boolean') ? data.config.enableTextClues : this.enableTextClues;
      }
      this.updateLobbyUI(networkManager.roomId);
      this.showScreen(this.screenLobby);
      this.showToast('Host returned everyone to lobby. New settings loaded! 🚀', 'info');
    };

    networkManager.listeners.onDrawerSelectMovie = (data) => {
      this.showMovieChoiceModal(data.choices);
    };

    networkManager.listeners.onDrawerChoosing = (data) => {
      this.showDrawerChoosingOverlay(data.drawerName);
    };

    networkManager.listeners.onDrawActionReceived = (action) => {
      if (this.drawingCanvas) {
        this.drawingCanvas.handleRemoteAction(action);
      }
    };

    networkManager.listeners.onDrawerChoseMovie = (chosenMovie) => {
      if (networkManager.isHost) {
        this.handleDrawerSelectedMovie(chosenMovie);
      }
    };

    networkManager.listeners.onAudioHintTriggered = async (playerId) => {
      if (networkManager.isHost) {
        this.usedAudioHint = true;
        const songQuery = this.currentPuzzle ? (this.currentPuzzle.songQuery || this.currentPuzzle.answer) : '';
        const track = await soundEngine.fetchSongPreviewUrl(songQuery);
        const payload = {
          type: 'PLAY_AUDIO_HINT',
          movieTitle: this.currentPuzzle ? this.currentPuzzle.answer : '',
          songQuery: songQuery,
          audioUrl: track ? track.audioUrl : null
        };
        networkManager.broadcast(payload);
        this.playSongTuneHint(payload);
      }
    };

    networkManager.listeners.onAudioHintPlayed = (data) => {
      this.playSongTuneHint(data);
    };

    networkManager.listeners.onAudioHintStopped = () => {
      this.stopSongTuneHint();
    };

    networkManager.listeners.onCameraStreamReceived = (remoteStream) => {
      this.handleRemoteCameraStream(remoteStream);
    };

    networkManager.listeners.onCameraStreamEnded = () => {
      this.handleRemoteCameraEnded();
    };

    networkManager.listeners.onCameraStateChanged = (data) => {
      this.handleCameraStateChanged(data);
    };

    
    networkManager.listeners.onPeerStreamReceived = (peerId, remoteStream) => {
      this.mountRemoteVideoTile(peerId, remoteStream);
    };

    networkManager.listeners.onPeerStreamEnded = (peerId) => {
      this.unmountVideoTile(peerId);
    };

    networkManager.listeners.onPeerMuteStateChanged = (data) => {
      this.handlePeerMuteStateChanged(data);
    };

    networkManager.listeners.onError = (msg) => {
      this.showToast(msg, 'error');
    };
  }

  renderPlayerRoster(players) {
    const list = document.getElementById('lobby-player-list');
    const countBadge = document.getElementById('lobby-player-count');
    if (!list) return;

    list.innerHTML = '';
    if (countBadge) countBadge.textContent = `${players.length} Player${players.length === 1 ? '' : 's'}`;

    players.forEach(p => {
      const card = document.createElement('div');
      card.className = `player-pill ${p.isHost ? 'host-pill' : ''} ${!p.connected ? 'offline' : ''}`;
      card.innerHTML = `
        <span class="player-avatar">${p.avatar}</span>
        <span class="player-name">${this.escapeHtml(p.name)}</span>
        ${p.isHost ? '<span class="host-badge">HOST</span>' : ''}
      `;
      list.appendChild(card);
    });
  }

  getCategoryLabel(category) {
    switch (category) {
      case 'movies': return '🎬 Movie';
      case 'songs': return '🎵 Song';
      case 'translations': return '🇬🇧➡️🇮🇳 Translation';
      case 'drawing': return '🎨 Draw & Guess';
      default: return '🔀 Mix';
    }
  }

  showMovieChoiceModal(choices) {
    const grid = document.getElementById('movie-choices-grid');
    if (!grid || !this.modalMovieSelection) return;
    grid.innerHTML = '';

    choices.forEach(puzzle => {
      const card = document.createElement('div');
      card.className = 'movie-choice-card';
      card.innerHTML = `
        <div>
          <div class="movie-choice-title">${this.escapeHtml(puzzle.answer)}</div>
          <div class="movie-choice-hint">${this.escapeHtml(puzzle.hint || 'Bollywood Hit')}</div>
        </div>
        <div class="movie-choice-arrow">➡️</div>
      `;
      card.addEventListener('click', () => {
        this.hideMovieChoiceModal();
        networkManager.sendDrawerChoice(puzzle);
      });
      grid.appendChild(card);
    });

    this.modalMovieSelection.classList.remove('hidden');
  }

  hideMovieChoiceModal() {
    if (this.modalMovieSelection) this.modalMovieSelection.classList.add('hidden');
  }

  showDrawerChoosingOverlay(drawerName) {
    const el = document.getElementById('choosing-drawer-name');
    if (el) el.textContent = `${drawerName || 'Drawer'} is choosing a movie...`;
    if (this.drawerChoosingOverlay) this.drawerChoosingOverlay.classList.remove('hidden');
  }

  hideDrawerChoosingOverlay() {
    if (this.drawerChoosingOverlay) this.drawerChoosingOverlay.classList.add('hidden');
  }

  async playSongTuneHint(data) {
    this.isPlayingAudioHint = true;
    const movieTitle = (typeof data === 'string') ? data : (data.movieTitle || '');
    const songQuery = (typeof data === 'object') ? (data.songQuery || '') : '';
    let audioUrl = (typeof data === 'object') ? (data.audioUrl || null) : null;

    if (!audioUrl && (songQuery || movieTitle)) {
      const track = await soundEngine.fetchSongPreviewUrl(songQuery || (movieTitle + ' bollywood song'));
      if (track) audioUrl = track.audioUrl;
    }

    const banner = document.getElementById('audio-tune-banner');
    const titleEl = document.getElementById('audio-tune-title');
    if (banner) {
      if (titleEl) {
        titleEl.innerHTML = '🎵 Playing 20s Song Tune Clue! <span class="unmute-badge">🔊 Tap to Listen</span>';
      }
      banner.classList.remove('hidden');
    }

    const isDrawer = (networkManager.playerId === this.activeDrawerId);
    const audioHintBtn = document.getElementById('btn-trigger-audio-hint');
    if (audioHintBtn && isDrawer) {
      audioHintBtn.disabled = false;
      audioHintBtn.innerHTML = '⏹️ Stop Song Tune';
      audioHintBtn.classList.add('btn-audio-stop');
    }

    
    await soundEngine.playMovieTuneHint(movieTitle, songQuery, audioUrl, 20);

    
    
    if (!isDrawer && audioUrl && !soundEngine.activeTrackAudio) {
      const promptModal = document.getElementById('modal-song-hint-prompt');
      if (promptModal) promptModal.classList.remove('hidden');
    }

    this.showToast('🎵 20-Second Movie Song Tune Hint is now playing!', 'info');

    if (this.tuneAutoStopTimer) clearTimeout(this.tuneAutoStopTimer);
    this.tuneAutoStopTimer = setTimeout(() => {
      if (this.isPlayingAudioHint) {
        this.stopSongTuneHint(false);
      }
    }, 20000);
  }

  stopSongTuneHint(showToastNotice = true) {
    this.isPlayingAudioHint = false;
    if (this.tuneAutoStopTimer) {
      clearTimeout(this.tuneAutoStopTimer);
      this.tuneAutoStopTimer = null;
    }
    soundEngine.stopMovieTune();

    const banner = document.getElementById('audio-tune-banner');
    if (banner) banner.classList.add('hidden');

    const promptModal = document.getElementById('modal-song-hint-prompt');
    if (promptModal) promptModal.classList.add('hidden');

    const audioHintBtn = document.getElementById('btn-trigger-audio-hint');
    if (audioHintBtn) {
      audioHintBtn.disabled = true;
      audioHintBtn.innerHTML = '🎵 Song Tune Played';
      audioHintBtn.classList.remove('btn-audio-stop');
    }

    if (showToastNotice) {
      this.showToast('⏹️ Song tune hint stopped.', 'info');
    }
  }

  

  async toggleCameraCharades() {
    if (this.isCameraActive) {
      this.stopCameraCharades();
    } else {
      await this.startCameraCharades();
    }
  }

  async startCameraCharades() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: this.cameraFacingMode,
          width: { ideal: 640 },
          height: { ideal: 480 }
        },
        audio: false
      });

      this.localCameraStream = stream;
      this.isCameraActive = true;

      const videoEl = document.getElementById('charades-video-feed');
      const videoContainer = document.getElementById('charades-video-container');
      const canvasWrapper = document.getElementById('canvas-wrapper');
      const drawingToolbar = document.getElementById('drawing-toolbar');
      const toggleBtn = document.getElementById('btn-toggle-camera');
      const flipBtn = document.getElementById('btn-flip-camera');
      const labelEl = document.getElementById('video-actor-label');

      if (videoEl) {
        videoEl.srcObject = stream;
        videoEl.className = (this.cameraFacingMode === 'environment') ? 'rear-cam' : '';
      }

      if (videoContainer) videoContainer.classList.remove('hidden');
      if (canvasWrapper) canvasWrapper.classList.add('hidden');
      if (drawingToolbar) drawingToolbar.classList.add('hidden');
      if (flipBtn) flipBtn.classList.remove('hidden');

      if (toggleBtn) {
        toggleBtn.innerHTML = '🎨 Switch to Drawing Canvas';
        toggleBtn.classList.add('active');
      }

      if (labelEl) {
        labelEl.innerHTML = '🎭 <strong>You</strong> are enacting the movie live on camera!';
      }

      
      const drawerPlayer = networkManager.players.get(networkManager.playerId);
      const actorName = drawerPlayer ? drawerPlayer.name : 'Actor';
      networkManager.startStreamingCamera(stream, actorName);

      this.showToast('📹 Camera live! Enact the movie for other players!', 'success');
    } catch (err) {
      console.error('Camera access denied or failed:', err);
      this.showToast('Camera access was not permitted. Please allow camera permissions to enact!', 'warning');
      this.isCameraActive = false;
    }
  }

  stopCameraCharades(notifyPeers = true) {
    if (this.localCameraStream) {
      try {
        this.localCameraStream.getTracks().forEach(t => t.stop());
      } catch (e) {}
      this.localCameraStream = null;
    }

    this.isCameraActive = false;

    const videoEl = document.getElementById('charades-video-feed');
    const videoContainer = document.getElementById('charades-video-container');
    const canvasWrapper = document.getElementById('canvas-wrapper');
    const drawingToolbar = document.getElementById('drawing-toolbar');
    const toggleBtn = document.getElementById('btn-toggle-camera');
    const flipBtn = document.getElementById('btn-flip-camera');

    if (videoEl) videoEl.srcObject = null;
    if (videoContainer) videoContainer.classList.add('hidden');
    if (canvasWrapper) canvasWrapper.classList.remove('hidden');
    if (flipBtn) flipBtn.classList.add('hidden');

    const isDrawer = (networkManager.playerId === this.activeDrawerId);
    if (isDrawer && drawingToolbar) {
      drawingToolbar.classList.remove('hidden');
    }

    if (toggleBtn) {
      toggleBtn.innerHTML = '📹 Enact on Camera 🎭';
      toggleBtn.classList.remove('active');
    }

    if (this.drawingCanvas) {
      requestAnimationFrame(() => {
        if (this.drawingCanvas) this.drawingCanvas.resize();
      });
    }

    if (notifyPeers) {
      networkManager.stopStreamingCamera();
    }
  }

  async flipCamera() {
    this.cameraFacingMode = (this.cameraFacingMode === 'user') ? 'environment' : 'user';
    this.stopCameraCharades(false);
    await this.startCameraCharades();
  }

  handleRemoteCameraStream(stream) {
    const videoEl = document.getElementById('charades-video-feed');
    const videoContainer = document.getElementById('charades-video-container');
    const canvasWrapper = document.getElementById('canvas-wrapper');
    const drawingToolbar = document.getElementById('drawing-toolbar');
    const flipBtn = document.getElementById('btn-flip-camera');

    if (videoEl) {
      videoEl.srcObject = stream;
      videoEl.className = 'rear-cam';
    }

    if (videoContainer) videoContainer.classList.remove('hidden');
    if (canvasWrapper) canvasWrapper.classList.add('hidden');
    if (drawingToolbar) drawingToolbar.classList.add('hidden');
    if (flipBtn) flipBtn.classList.add('hidden'); 
  }

  handleRemoteCameraEnded() {
    const videoEl = document.getElementById('charades-video-feed');
    const videoContainer = document.getElementById('charades-video-container');
    const canvasWrapper = document.getElementById('canvas-wrapper');

    if (videoEl) videoEl.srcObject = null;
    if (videoContainer) videoContainer.classList.add('hidden');
    if (canvasWrapper) canvasWrapper.classList.remove('hidden');

    if (this.drawingCanvas) {
      requestAnimationFrame(() => {
        if (this.drawingCanvas) this.drawingCanvas.resize();
      });
    }
  }

  handleCameraStateChanged(data) {
    const videoContainer = document.getElementById('charades-video-container');
    const canvasWrapper = document.getElementById('canvas-wrapper');
    const labelEl = document.getElementById('video-actor-label');

    if (data.enabled) {
      if (videoContainer) videoContainer.classList.remove('hidden');
      if (canvasWrapper) canvasWrapper.classList.add('hidden');
      if (labelEl) {
        labelEl.innerHTML = `🎭 <strong>${this.escapeHtml(data.actorName || 'Actor')}</strong> is enacting the movie live!`;
      }
    } else {
      this.handleRemoteCameraEnded();
    }
  }

  

  async initGroupCallMedia() {
    if (this.groupMediaStream) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: this.callCamFacingMode,
          width: { ideal: 480, max: 640 },
          height: { ideal: 360, max: 480 },
          frameRate: { ideal: 24, max: 30 }
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      });

      this.groupMediaStream = stream;
      this.mountLocalVideoTile(stream);
      networkManager.callAllPeers(stream);

      if (this.callControlsBar) this.callControlsBar.classList.remove('hidden');
      if (this.videoCallSection) this.videoCallSection.classList.remove('hidden');
      this.updateCallPlayerCount();
      this.showToast('🎙️ Live Group Video & Audio Connected!', 'success');
    } catch (err) {
      console.warn('Group call media request not granted or unavailable:', err);
      this.mountLocalAvatarTile();
      if (this.callControlsBar) this.callControlsBar.classList.remove('hidden');
      if (this.videoCallSection) this.videoCallSection.classList.remove('hidden');
      this.updateCallPlayerCount();
    }
  }

  mountLocalVideoTile(stream) {
    const myId = networkManager.playerId || 'local';
    this.unmountVideoTile(myId);

    const tile = document.createElement('div');
    tile.id = `tile-${myId}`;
    tile.className = 'video-tile is-local';
    if (this.activeDrawerId === myId) tile.classList.add('actor-spotlight');

    const video = document.createElement('video');
    video.autoplay = true;
    video.playsInline = true;
    video.muted = true; 
    video.srcObject = stream;
    if (this.callCamFacingMode === 'environment') video.className = 'rear-cam';
    video.play().catch(() => {});

    const avatarFallback = document.createElement('div');
    avatarFallback.className = 'avatar-fallback hidden';
    avatarFallback.innerHTML = `<span class="tile-avatar-emoji">${this.selectedAvatar}</span>`;

    const statusBar = document.createElement('div');
    statusBar.className = 'tile-status-bar';
    statusBar.innerHTML = `
      <span class="tile-player-name">👤 You (${this.escapeHtml(networkManager.playerName || 'Me')})</span>
      <span id="tile-mic-${myId}" class="tile-mic-icon">🎙️</span>
    `;

    tile.appendChild(video);
    tile.appendChild(avatarFallback);
    tile.appendChild(statusBar);

    const targetGrid = this.isHangoutMode
      ? (document.getElementById('hangout-video-gallery') || this.videoCallGrid)
      : this.videoCallGrid;
    if (targetGrid) targetGrid.prepend(tile);

    this.videoTiles.set(myId, { tile, video, avatarFallback, stream, isLocal: true });
    this.updateCallPlayerCount();
    this.updateActorSpotlight();
  }

  mountLocalAvatarTile() {
    const myId = networkManager.playerId || 'local';
    this.unmountVideoTile(myId);

    const tile = document.createElement('div');
    tile.id = `tile-${myId}`;
    tile.className = 'video-tile is-local camera-off';
    if (this.activeDrawerId === myId) tile.classList.add('actor-spotlight');

    const avatarFallback = document.createElement('div');
    avatarFallback.className = 'avatar-fallback';
    avatarFallback.innerHTML = `<span class="tile-avatar-emoji">${this.selectedAvatar}</span>`;

    const statusBar = document.createElement('div');
    statusBar.className = 'tile-status-bar';
    statusBar.innerHTML = `
      <span class="tile-player-name">👤 You (${this.escapeHtml(networkManager.playerName || 'Me')})</span>
      <span id="tile-mic-${myId}" class="tile-mic-icon muted">🔇</span>
    `;

    tile.appendChild(avatarFallback);
    tile.appendChild(statusBar);

    const targetGrid = this.isHangoutMode
      ? (document.getElementById('hangout-video-gallery') || this.videoCallGrid)
      : this.videoCallGrid;
    if (targetGrid) targetGrid.prepend(tile);

    this.videoTiles.set(myId, { tile, video: null, avatarFallback, stream: null, isLocal: true });
    this.updateCallPlayerCount();
    this.updateActorSpotlight();
  }

  mountRemoteVideoTile(peerId, stream) {
    if (!peerId || !stream) return;
    this.unmountVideoTile(peerId);

    const player = Array.from(networkManager.players.values()).find(p => p.id === peerId || p.peerId === peerId) || { name: 'Player', avatar: '👤' };
    const effectiveId = player.id || peerId;

    const tile = document.createElement('div');
    tile.id = `tile-${effectiveId}`;
    tile.className = 'video-tile';
    if (this.activeDrawerId === effectiveId || this.activeDrawerId === peerId) {
      tile.classList.add('actor-spotlight');
    }

    const video = document.createElement('video');
    video.autoplay = true;
    video.playsInline = true;
    video.setAttribute('playsinline', 'true');
    video.setAttribute('webkit-playsinline', 'true');
    video.muted = false; 
    video.volume = 1.0;
    video.srcObject = stream;
    video.onloadedmetadata = () => {
      video.play().catch(e => console.warn('Remote video autoplay waiting for interaction:', e));
    };
    video.play().catch(() => {});

    const avatarFallback = document.createElement('div');
    avatarFallback.className = 'avatar-fallback hidden';
    avatarFallback.innerHTML = `<span class="tile-avatar-emoji">${player.avatar || '👤'}</span>`;

    const statusBar = document.createElement('div');
    statusBar.className = 'tile-status-bar';
    statusBar.innerHTML = `
      <span class="tile-player-name">${player.avatar || '👤'} ${this.escapeHtml(player.name || 'Player')}</span>
      <span id="tile-mic-${effectiveId}" class="tile-mic-icon">🎙️</span>
    `;

    tile.appendChild(video);
    tile.appendChild(avatarFallback);
    tile.appendChild(statusBar);

    const targetGrid = this.isHangoutMode
      ? (document.getElementById('hangout-video-gallery') || this.videoCallGrid)
      : this.videoCallGrid;
    if (targetGrid) targetGrid.appendChild(tile);

    const tileData = { tile, video, avatarFallback, stream, isLocal: false };
    this.videoTiles.set(effectiveId, tileData);
    this.videoTiles.set(peerId, tileData);

    this.updateCallPlayerCount();
    this.updateActorSpotlight();
  }

  unmountVideoTile(peerId) {
    if (!peerId) return;
    const player = Array.from(networkManager.players.values()).find(p => p.id === peerId || p.peerId === peerId);
    const idsToClean = [peerId];
    if (player) {
      if (player.id) idsToClean.push(player.id);
      if (player.peerId) idsToClean.push(player.peerId);
    }

    idsToClean.forEach(id => {
      if (this.videoTiles.has(id)) {
        const { tile, video } = this.videoTiles.get(id);
        if (video) {
          try { video.srcObject = null; } catch (e) {}
        }
        if (tile && tile.parentNode) tile.parentNode.removeChild(tile);
        this.videoTiles.delete(id);
      }
      const el = document.getElementById(`tile-${id}`);
      if (el) el.remove();
    });

    this.updateCallPlayerCount();
  }

  unmountAllVideoTiles() {
    this.videoTiles.forEach(({ tile, video }) => {
      if (video) {
        try { video.srcObject = null; } catch (e) {}
      }
      if (tile && tile.parentNode) tile.parentNode.removeChild(tile);
    });
    this.videoTiles.clear();
    const grid = document.getElementById('video-call-grid');
    if (grid) grid.innerHTML = '';
    const gallery = document.getElementById('hangout-video-gallery');
    if (gallery) gallery.innerHTML = '';
    this.updateCallPlayerCount();
  }

  toggleCallMic() {
    if (!this.groupMediaStream) return;
    const audioTracks = this.groupMediaStream.getAudioTracks();
    if (audioTracks.length === 0) return;

    this.isCallMicMuted = !this.isCallMicMuted;
    audioTracks.forEach(t => t.enabled = !this.isCallMicMuted);

    const micBtn = document.getElementById('btn-call-mic');
    const micIcon = document.getElementById('call-mic-icon');
    const micLabel = document.getElementById('call-mic-label');
    const myId = networkManager.playerId || 'local';
    const localMicBadge = document.getElementById(`tile-mic-${myId}`);

    if (this.isCallMicMuted) {
      if (micBtn) micBtn.classList.add('is-muted');
      if (micIcon) micIcon.textContent = '🔇';
      if (micLabel) micLabel.textContent = 'Unmute';
      if (localMicBadge) {
        localMicBadge.textContent = '🔇';
        localMicBadge.classList.add('muted');
      }
      this.showToast('Microphone muted 🔇', 'info');
    } else {
      if (micBtn) micBtn.classList.remove('is-muted');
      if (micIcon) micIcon.textContent = '🎙️';
      if (micLabel) micLabel.textContent = 'Mute';
      if (localMicBadge) {
        localMicBadge.textContent = '🎙️';
        localMicBadge.classList.remove('muted');
      }
      this.showToast('Microphone live 🎙️', 'info');
    }

    networkManager.broadcastMuteState(this.isCallMicMuted, this.isCallCamOff);
  }

  async toggleCallCam() {
    const camBtn = document.getElementById('btn-call-cam');
    const camIcon = document.getElementById('call-cam-icon');
    const camLabel = document.getElementById('call-cam-label');
    const myId = networkManager.playerId || 'local';
    const myTileData = this.videoTiles.get(myId);

    if (!this.isCallCamOff) {
      
      if (this.groupMediaStream) {
        const videoTracks = this.groupMediaStream.getVideoTracks();
        videoTracks.forEach(t => {
          t.stop();
          this.groupMediaStream.removeTrack(t);
        });
      }

      this.isCallCamOff = true;
      if (myTileData?.video) myTileData.video.srcObject = null;
      if (myTileData?.avatarFallback) myTileData.avatarFallback.classList.remove('hidden');

      if (camBtn) camBtn.classList.add('is-off');
      if (camIcon) camIcon.textContent = '🚫';
      if (camLabel) camLabel.textContent = 'Start Video';

      this.showToast('Camera hardware turned off', 'info');
      networkManager.broadcastMuteState(this.isCallMicMuted, true);
    } else {
      
      try {
        const newStream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: this.callCamFacingMode,
            width: { ideal: 480, max: 640 },
            height: { ideal: 360, max: 480 },
            frameRate: { ideal: 24, max: 30 }
          }
        });

        const newVideoTrack = newStream.getVideoTracks()[0];
        if (this.groupMediaStream) {
          this.groupMediaStream.addTrack(newVideoTrack);
        } else {
          this.groupMediaStream = newStream;
        }

        this.isCallCamOff = false;
        if (myTileData?.video) {
          myTileData.video.srcObject = this.groupMediaStream;
          myTileData.video.play().catch(() => {});
        }
        if (myTileData?.avatarFallback) myTileData.avatarFallback.classList.add('hidden');

        if (camBtn) camBtn.classList.remove('is-off');
        if (camIcon) camIcon.textContent = '📹';
        if (camLabel) camLabel.textContent = 'Stop Video';

        networkManager.callAllPeers(this.groupMediaStream);
        networkManager.broadcastMuteState(this.isCallMicMuted, false);
        this.showToast('Camera live 📹', 'info');
      } catch (err) {
        console.warn('Could not re-enable camera:', err);
        this.showToast('Camera access was not granted.', 'warning');
      }
    }
  }

  async flipCallCam() {
    if (!this.groupMediaStream || this.isCallCamOff) return;
    this.callCamFacingMode = (this.callCamFacingMode === 'user') ? 'environment' : 'user';

    try {
      const newStream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: this.callCamFacingMode,
          width: { ideal: 480, max: 640 },
          height: { ideal: 360, max: 480 }
        }
      });

      const newVideoTrack = newStream.getVideoTracks()[0];
      const oldVideoTrack = this.groupMediaStream.getVideoTracks()[0];

      if (oldVideoTrack) {
        this.groupMediaStream.removeTrack(oldVideoTrack);
        oldVideoTrack.stop();
      }

      this.groupMediaStream.addTrack(newVideoTrack);

      const myId = networkManager.playerId || 'local';
      const myTileData = this.videoTiles.get(myId);
      if (myTileData?.video) {
        myTileData.video.srcObject = this.groupMediaStream;
        myTileData.video.className = (this.callCamFacingMode === 'environment') ? 'rear-cam' : '';
        myTileData.video.play().catch(() => {});
      }

      networkManager.callAllPeers(this.groupMediaStream);
      this.showToast('Camera flipped 🔄', 'info');
    } catch (e) {
      console.warn('Could not flip camera:', e);
    }
  }

  toggleVideoViewMode() {
    this.isFocusActorMode = !this.isFocusActorMode;
    const section = document.getElementById('video-call-section');
    const toggleBtn = document.getElementById('btn-toggle-video-view');

    if (section) {
      section.classList.toggle('focus-actor-mode', this.isFocusActorMode);
    }

    if (toggleBtn) {
      toggleBtn.classList.toggle('active', this.isFocusActorMode);
      toggleBtn.textContent = this.isFocusActorMode ? '👥 All Videos' : '🎭 Focus Actor';
    }

    this.updateActorSpotlight();
    this.showToast(this.isFocusActorMode ? 'Spotlight mode: Focusing on actor feed' : 'Grid view: Showing all player videos', 'info');
  }

  updateActorSpotlight() {
    const actorId = this.activeDrawerId;
    this.videoTiles.forEach((tileData, peerId) => {
      const isActor = (actorId && peerId === actorId);
      if (tileData.tile) {
        tileData.tile.classList.toggle('actor-spotlight', !!isActor);

        
        let badge = tileData.tile.querySelector('.tile-actor-badge');
        if (isActor) {
          if (!badge) {
            badge = document.createElement('div');
            badge.className = 'tile-actor-badge';
            badge.textContent = '🎭 ENACTING';
            tileData.tile.appendChild(badge);
          }
        } else if (badge) {
          badge.remove();
        }
      }
    });
  }

  toggleCallCollapse() {
    this.isVideoStripCollapsed = !this.isVideoStripCollapsed;
    const section = document.getElementById('video-call-section');
    const collapseBtn = document.getElementById('btn-call-collapse');
    const collapseIcon = document.getElementById('call-collapse-icon');
    const collapseLabel = document.getElementById('call-collapse-label');
    const topCollapseIcon = document.getElementById('collapse-icon');

    if (section) section.classList.toggle('collapsed', this.isVideoStripCollapsed);

    if (this.isVideoStripCollapsed) {
      if (collapseIcon) collapseIcon.textContent = '👁️‍🗨️';
      if (collapseLabel) collapseLabel.textContent = 'Show Video';
      if (topCollapseIcon) topCollapseIcon.textContent = '▼';
    } else {
      if (collapseIcon) collapseIcon.textContent = '👁️';
      if (collapseLabel) collapseLabel.textContent = 'Hide Video';
      if (topCollapseIcon) topCollapseIcon.textContent = '▲';
    }
  }

  handlePeerMuteStateChanged(data) {
    const tileData = this.videoTiles.get(data.peerId);
    if (tileData) {
      if (data.isVideoOff) {
        tileData.avatarFallback?.classList.remove('hidden');
      } else {
        tileData.avatarFallback?.classList.add('hidden');
      }
    }
    const micBadge = document.getElementById(`tile-mic-${data.peerId}`);
    if (micBadge) {
      if (data.isAudioMuted) {
        micBadge.textContent = '🔇';
        micBadge.classList.add('muted');
      } else {
        micBadge.textContent = '🎙️';
        micBadge.classList.remove('muted');
      }
    }
  }

  updateCallPlayerCount() {
    const count = this.videoTiles.size || (networkManager.players.size || 1);
    const badge = document.getElementById('call-player-count-badge');
    if (badge) badge.textContent = `${count}`;
  }

  stopGroupCallMedia() {
    if (this.groupMediaStream) {
      try {
        this.groupMediaStream.getTracks().forEach(t => t.stop());
      } catch (e) {}
      this.groupMediaStream = null;
    }
    if (this.callControlsBar) this.callControlsBar.classList.add('hidden');
    if (this.videoCallGrid) this.videoCallGrid.innerHTML = '';
    this.videoTiles.clear();
  }

  

  startHangoutLounge() {
    this.isHangoutMode = true;
    this.showScreen(this.screenGame);

    const videoSection = document.getElementById('video-call-section');
    const hangoutStage = document.getElementById('hangout-call-stage');
    const normalGame = document.getElementById('normal-game-elements');
    const roomBadge = document.getElementById('hangout-room-code-badge');

    if (videoSection) videoSection.classList.add('hidden');
    if (normalGame) normalGame.classList.add('hidden');
    if (hangoutStage) hangoutStage.classList.remove('hidden');
    if (roomBadge) roomBadge.textContent = networkManager.roomId || '----';

    
    this.hangoutSeconds = 0;
    if (this.hangoutInterval) clearInterval(this.hangoutInterval);
    this.hangoutInterval = setInterval(() => {
      this.hangoutSeconds++;
      const mins = String(Math.floor(this.hangoutSeconds / 60)).padStart(2, '0');
      const secs = String(this.hangoutSeconds % 60).padStart(2, '0');
      const timerPill = document.getElementById('hangout-call-timer');
      if (timerPill) timerPill.textContent = `⏱️ ${mins}:${secs}`;
    }, 1000);

    
    if (!this.groupMediaStream) {
      this.initGroupCallMedia();
    } else {
      this.remountHangoutVideoTiles();
      networkManager.callAllPeers(this.groupMediaStream);
    }

    this.updateCallPlayerCount();
    this.showToast('📹 Group Video Hangout active!', 'success');
  }

  remountHangoutVideoTiles() {
    const gallery = document.getElementById('hangout-video-gallery');
    if (!gallery) return;
    gallery.innerHTML = '';
    this.videoTiles.forEach((data) => {
      if (data.tile) gallery.appendChild(data.tile);
    });
  }

  triggerFlyingEmoji(emoji) {
    const canvas = document.getElementById('floating-reactions-canvas');
    if (!canvas) return;
    const el = document.createElement('div');
    el.className = 'flying-emoji';
    el.textContent = emoji;
    el.style.left = `${Math.floor(Math.random() * 70) + 15}%`;
    canvas.appendChild(el);
    setTimeout(() => el.remove(), 2500);
  }

  addHangoutChatMessage(author, avatar, text, isMe) {
    const messages = document.getElementById('hangout-chat-messages');
    if (!messages) return;
    const bubble = document.createElement('div');
    bubble.className = `chat-bubble ${isMe ? 'is-me' : ''}`;
    bubble.innerHTML = `
      <div class="chat-author">${avatar || '👤'} ${this.escapeHtml(author || 'Player')}</div>
      <div class="chat-text">${this.escapeHtml(text)}</div>
    `;
    messages.appendChild(bubble);
    messages.scrollTop = messages.scrollHeight;
  }

  

  startMultiplayerGame() {
    if (this.selectedCategory === 'hangout') {
      networkManager.gameState = 'HANGOUT';
      networkManager.gameConfig = {
        category: 'hangout',
        isHangoutMode: true
      };
      networkManager.broadcast({
        type: 'GAME_STARTED',
        category: 'hangout',
        isHangoutMode: true
      });
      this.startHangoutLounge();
      return;
    }

    networkManager.gameState = 'PLAYING';
    networkManager.gameConfig = {
      category: this.selectedCategory,
      roundDuration: this.roundDuration,
      totalRounds: this.totalRounds
    };

    
    this.puzzles = window.deckManager.getPuzzles({
      category: this.selectedCategory,
      source: this.selectedDeckSource,
      count: this.totalRounds
    });

    if (this.puzzles.length === 0) {
      this.showToast('No puzzles found in chosen category! Check custom deck.', 'error');
      return;
    }

    this.currentRound = 0;
    
    networkManager.players.forEach(p => {
      p.score = 0;
      p.hasGuessedThisRound = false;
      p.roundPoints = 0;
    });
    networkManager.broadcastPlayerList();

    networkManager.broadcast({
      type: 'GAME_STARTED',
      totalRounds: this.puzzles.length,
      roundDuration: this.roundDuration
    });

    this.startNextRound();
  }

  startNextRound() {
    if (this.currentRound >= this.puzzles.length) {
      this.finishGame();
      return;
    }

    this.currentRound++;
    this.correctGuessCount = 0;
    this.timeRemaining = this.roundDuration;
    this.revealedLetters.clear();
    this.usedAudioHint = false;

    
    networkManager.players.forEach(p => {
      p.hasGuessedThisRound = false;
      p.roundPoints = 0;
    });

    const isInteractiveCategory = (this.selectedCategory === 'drawing' || this.selectedCategory === 'charades');

    if (isInteractiveCategory) {
      const activePlayers = Array.from(networkManager.players.values()).filter(p => p.connected);
      const drawerIdx = (this.currentRound - 1) % activePlayers.length;
      const activeDrawer = activePlayers[drawerIdx] || activePlayers[0];
      this.activeDrawerId = activeDrawer.id;

      const choices = window.deckManager.getThreeMovieChoices();

      if (activeDrawer.id === networkManager.playerId) {
        
        this.hideDrawerChoosingOverlay();
        this.showMovieChoiceModal(choices);
        networkManager.broadcast({
          type: 'DRAWER_CHOOSING',
          drawerName: activeDrawer.name
        });
      } else {
        
        networkManager.sendToPlayer(activeDrawer.id, {
          type: 'DRAWER_SELECT_MOVIE',
          drawerId: activeDrawer.id,
          choices: choices
        });
        networkManager.broadcastExcept(activeDrawer.id, {
          type: 'DRAWER_CHOOSING',
          drawerName: activeDrawer.name
        });
        this.showDrawerChoosingOverlay(activeDrawer.name);
      }
      return;
    }

    
    this.currentPuzzle = this.puzzles[this.currentRound - 1];
    this.launchRoundForCurrentPuzzle();
  }

  handleDrawerSelectedMovie(chosenMovie) {
    this.hideDrawerChoosingOverlay();
    this.hideMovieChoiceModal();
    this.currentPuzzle = chosenMovie;
    this.launchRoundForCurrentPuzzle();
  }

  launchRoundForCurrentPuzzle() {
    this.hideDrawerChoosingOverlay();
    this.hideMovieChoiceModal();

    const isInteractiveCategory = (this.selectedCategory === 'drawing' || this.selectedCategory === 'charades');
    const activeCategory = isInteractiveCategory ? this.selectedCategory : this.currentPuzzle.category;

    const roundData = {
      roundNumber: this.currentRound,
      totalRounds: this.puzzles.length,
      roundDuration: this.roundDuration,
      category: activeCategory,
      emojis: this.currentPuzzle.emojis || (this.selectedCategory === 'charades' ? '🎭📹' : '🎬🎨'),
      englishTranslation: this.currentPuzzle.englishTranslation || '',
      hintBlanks: this.generateHintBlanks(this.currentPuzzle.answer),
      categoryLabel: this.getCategoryLabel(activeCategory),
      clueHint: this.enableTextClues ? (this.currentPuzzle.hint || '') : '',
      enableTextClues: this.enableTextClues,
      activeDrawerId: this.activeDrawerId,
      secretAnswer: this.currentPuzzle.answer
    };

    networkManager.broadcast({
      type: 'ROUND_STARTED',
      ...roundData
    });

    this.startRoundClient(roundData);
    this.startHostTimer();
  }

  startHostTimer() {
    if (this.timerInterval) clearInterval(this.timerInterval);

    this.timerInterval = setInterval(() => {
      this.timeRemaining--;

      
      const totalLetters = (this.currentPuzzle.answer.match(/[a-zA-Z0-9]/g) || []).length;
      const stage1 = Math.floor(this.roundDuration * 0.70);
      const stage2 = Math.floor(this.roundDuration * 0.45);
      const stage3 = Math.floor(this.roundDuration * 0.20);

      if (this.correctGuessCount === 0) {
        if (this.timeRemaining === stage1) {
          this.revealProgressiveLetter();
        } else if (this.timeRemaining === stage2 && totalLetters >= 5) {
          this.revealProgressiveLetter();
        } else if (this.timeRemaining === stage3 && totalLetters >= 8) {
          this.revealProgressiveLetter();
        }
      }

      networkManager.broadcast({
        type: 'TIME_SYNC',
        timeRemaining: this.timeRemaining,
        totalTime: this.roundDuration
      });

      this.updateTimerDisplay(this.timeRemaining, this.roundDuration);

      if (this.timeRemaining <= 0) {
        clearInterval(this.timerInterval);
        this.endCurrentRound();
      }
    }, 1000);
  }

  revealProgressiveLetter() {
    if (!this.currentPuzzle) return;
    const answer = this.currentPuzzle.answer;
    const words = answer.trim().split(/\s+/);
    let charIdx = 0;
    const wordList = [];
    let totalAlphanumeric = 0;

    words.forEach(word => {
      const indices = [];
      for (let i = 0; i < word.length; i++) {
        if (/[a-zA-Z0-9]/.test(word[i])) {
          indices.push(charIdx);
          totalAlphanumeric++;
        }
        charIdx++;
      }
      charIdx++; 
      wordList.push(indices);
    });

    const maxReveals = totalAlphanumeric <= 3 ? 1 : Math.max(1, Math.min(Math.floor(totalAlphanumeric * 0.45), 4));
    if (this.revealedLetters.size >= maxReveals) return;

    
    const unrevealedWords = wordList.filter(indices => !indices.some(idx => this.revealedLetters.has(idx)));
    let candidatePool = [];

    if (unrevealedWords.length > 0) {
      const chosenWordIndices = unrevealedWords[Math.floor(Math.random() * unrevealedWords.length)];
      candidatePool = chosenWordIndices.filter(idx => !this.revealedLetters.has(idx));
    }

    if (candidatePool.length === 0) {
      
      candidatePool = [];
      wordList.forEach(indices => {
        indices.forEach(idx => {
          if (!this.revealedLetters.has(idx)) candidatePool.push(idx);
        });
      });
    }

    if (candidatePool.length > 0) {
      const pickedIndex = candidatePool[Math.floor(Math.random() * candidatePool.length)];
      this.revealedLetters.add(pickedIndex);

      const updatedBlanks = this.generateHintBlanks(answer, this.revealedLetters);
      networkManager.broadcast({
        type: 'HINT_UPDATE',
        hintBlanks: updatedBlanks
      });
      this.renderHintBlanks(updatedBlanks);
      soundEngine.playTick(true);
    }
  }

  

  startRoundClient(data) {
    this.hasGuessed = false;
    this.guessLog = [];
    this.activeDrawerId = data.activeDrawerId || null;
    this.updateActorSpotlight();
    this.stopCameraCharades(false);
    this.hideDrawerChoosingOverlay();
    this.hideMovieChoiceModal();

    
    this.showScreen(this.screenGame);

    document.getElementById('guess-input').value = '';
    document.getElementById('guess-input').disabled = false;
    document.getElementById('btn-submit-guess').disabled = false;
    document.getElementById('guess-feedback').textContent = '';
    document.getElementById('guess-feedback').className = 'guess-feedback';
    document.getElementById('live-guess-feed').innerHTML = '';

    
    document.getElementById('game-round-badge').textContent = `Round ${data.roundNumber} / ${data.totalRounds}`;
    document.getElementById('game-category-badge').textContent = data.categoryLabel;
    document.getElementById('game-emojis').textContent = data.emojis;
    document.getElementById('game-clue-hint').textContent = data.clueHint ? `💡 Hint: ${data.clueHint}` : '';

    
    const emojiStage = document.getElementById('emoji-stage-box');
    const drawingStage = document.getElementById('game-drawing-stage');
    const drawerBanner = document.getElementById('drawer-secret-banner');
    const drawerSecretWord = document.getElementById('drawer-secret-word');
    const guesserBanner = document.getElementById('guesser-drawer-banner');
    const guesserDrawerText = document.getElementById('guesser-drawer-text');
    const drawingToolbar = document.getElementById('drawing-toolbar');
    const guessForm = document.getElementById('guess-form');
    const audioTuneBanner = document.getElementById('audio-tune-banner');
    const audioHintBtn = document.getElementById('btn-trigger-audio-hint');

    if (audioTuneBanner) audioTuneBanner.classList.add('hidden');
    if (audioHintBtn) {
      audioHintBtn.disabled = false;
      audioHintBtn.innerHTML = '🎵 Play Song Tune Hint <span class="penalty-tag">(-30 pts)</span>';
    }

    if (data.category === 'drawing' || data.category === 'charades') {
      if (emojiStage) emojiStage.classList.add('hidden');
      if (drawingStage) drawingStage.classList.remove('hidden');

      const isDrawer = (networkManager.playerId === data.activeDrawerId);
      const isCharades = (data.category === 'charades');
      const canvasWrapper = document.getElementById('canvas-wrapper');
      const charadesVideo = document.getElementById('charades-video-container');

      if (isCharades) {
        if (canvasWrapper) canvasWrapper.classList.add('hidden');
        if (drawingToolbar) drawingToolbar.classList.add('hidden');

        if (isDrawer) {
          if (drawerBanner) drawerBanner.classList.remove('hidden');
          if (drawerSecretWord) drawerSecretWord.textContent = data.secretAnswer;
          if (guesserBanner) guesserBanner.classList.add('hidden');
          if (guessForm) guessForm.classList.add('hidden');
          
          this.startCameraCharades();
        } else {
          const drawerPlayer = networkManager.players.get(data.activeDrawerId);
          const drawerName = drawerPlayer ? drawerPlayer.name : 'Player';
          if (drawerBanner) drawerBanner.classList.add('hidden');
          if (guesserBanner) {
            guesserBanner.classList.remove('hidden');
            if (guesserDrawerText) guesserDrawerText.innerHTML = `🎭 <strong>${this.escapeHtml(drawerName)}</strong> is enacting the movie on camera!`;
          }
          if (guessForm) guessForm.classList.remove('hidden');
        }
      } else {
        
        if (charadesVideo) charadesVideo.classList.add('hidden');
        if (canvasWrapper) canvasWrapper.classList.remove('hidden');
        if (this.drawingCanvas) {
          this.drawingCanvas.clearLocal(false);
          this.drawingCanvas.setReadOnly(!isDrawer);
          requestAnimationFrame(() => {
            if (this.drawingCanvas) this.drawingCanvas.resize();
          });
          setTimeout(() => {
            if (this.drawingCanvas) this.drawingCanvas.resize();
          }, 50);
        }

        if (isDrawer) {
          if (drawerBanner) drawerBanner.classList.remove('hidden');
          if (drawerSecretWord) drawerSecretWord.textContent = data.secretAnswer;
          if (guesserBanner) guesserBanner.classList.add('hidden');
          if (drawingToolbar) drawingToolbar.classList.remove('hidden');
          if (guessForm) guessForm.classList.add('hidden');
        } else {
          const drawerPlayer = networkManager.players.get(data.activeDrawerId);
          const drawerName = drawerPlayer ? drawerPlayer.name : 'Player';
          if (drawerBanner) drawerBanner.classList.add('hidden');
          if (guesserBanner) {
            guesserBanner.classList.remove('hidden');
            if (guesserDrawerText) guesserDrawerText.innerHTML = `🎨 <strong>${this.escapeHtml(drawerName)}</strong> is drawing...`;
          }
          if (drawingToolbar) drawingToolbar.classList.add('hidden');
          if (guessForm) guessForm.classList.remove('hidden');
        }
      }
    } else {
      if (emojiStage) emojiStage.classList.remove('hidden');
      if (drawingStage) drawingStage.classList.add('hidden');
      if (drawerBanner) drawerBanner.classList.add('hidden');
      if (guesserBanner) guesserBanner.classList.add('hidden');
      if (drawingToolbar) drawingToolbar.classList.add('hidden');
      if (guessForm) guessForm.classList.remove('hidden');
    }

    
    const transBox = document.getElementById('game-translation-box');
    const transText = document.getElementById('game-translation-text');
    if (data.englishTranslation && transBox && transText && data.category !== 'drawing' && data.category !== 'charades') {
      transText.textContent = `"${data.englishTranslation}"`;
      transBox.classList.remove('hidden');
    } else if (transBox) {
      transBox.classList.add('hidden');
    }

    this.renderHintBlanks(data.hintBlanks);
    this.updateTimerDisplay(data.roundDuration, data.roundDuration);
    soundEngine.playRoundStart();

    
    const isActorOrDrawer = (networkManager.playerId === data.activeDrawerId && (data.category === 'drawing' || data.category === 'charades'));
    if (!isActorOrDrawer) {
      setTimeout(() => {
        document.getElementById('guess-input')?.focus();
      }, 300);
    }
  }

  updateTimerDisplay(timeRemaining, totalTime) {
    const timerText = document.getElementById('timer-seconds');
    const timerRing = document.getElementById('timer-circle-progress');
    if (!timerText) return;

    timerText.textContent = Math.max(0, timeRemaining);

    if (timerRing) {
      const circumference = 2 * Math.PI * 42; 
      const percent = Math.max(0, timeRemaining / totalTime);
      const offset = circumference * (1 - percent);
      timerRing.style.strokeDasharray = `${circumference}`;
      timerRing.style.strokeDashoffset = `${offset}`;

      if (timeRemaining <= 5) {
        timerRing.style.stroke = '#ef4444'; 
        soundEngine.playTick(true);
      } else if (timeRemaining <= 10) {
        timerRing.style.stroke = '#f59e0b'; 
        soundEngine.playTick(false);
      } else {
        timerRing.style.stroke = '#6366f1'; 
      }
    }
  }

  

  
  generateHintBlanks(answer, revealedIndices = new Set()) {
    const words = answer.trim().split(/\s+/);
    let charIndex = 0;
    const structure = [];

    words.forEach(word => {
      const letters = [];
      for (let i = 0; i < word.length; i++) {
        const char = word[i];
        const isAlphanumeric = /[a-zA-Z0-9]/.test(char);
        if (isAlphanumeric) {
          if (revealedIndices.has(charIndex)) {
            letters.push({ type: 'revealed', char: char });
          } else {
            letters.push({ type: 'blank', char: '_' });
          }
        } else {
          
          letters.push({ type: 'symbol', char: char });
        }
        charIndex++;
      }
      charIndex++; 
      structure.push(letters);
    });

    return structure;
  }

  renderHintBlanks(blanksStructure) {
    const container = document.getElementById('game-hint-blanks');
    if (!container) return;
    container.innerHTML = '';

    blanksStructure.forEach(word => {
      const wordContainer = document.createElement('div');
      wordContainer.className = 'hint-word';

      word.forEach(item => {
        const slot = document.createElement('span');
        if (item.type === 'blank') {
          slot.className = 'hint-letter blank';
          slot.textContent = '';
        } else if (item.type === 'revealed') {
          slot.className = 'hint-letter revealed';
          slot.textContent = item.char;
        } else {
          slot.className = 'hint-letter symbol';
          slot.textContent = item.char;
        }
        wordContainer.appendChild(slot);
      });

      container.appendChild(wordContainer);
    });
  }

  

  handleGuessSubmit() {
    if (this.hasGuessed) return;
    const input = document.getElementById('guess-input');
    const guess = input.value.trim();
    if (!guess) return;

    if (networkManager.isHost) {
      this.evaluateGuess(networkManager.playerId, guess, this.timeRemaining);
    } else {
      networkManager.submitGuess(guess, this.timeRemaining);
    }

    input.value = '';
    input.focus();
  }

  normalizeAnswer(str) {
    return str
      .toLowerCase()
      .replace(/^(the|a|an)\s+/i, '') 
      .replace(/[^a-z0-9]/g, '') 
      .trim();
  }

  levenshtein(a, b) {
    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;
    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1,
            matrix[i][j - 1] + 1,
            matrix[i - 1][j] + 1
          );
        }
      }
    }
    return matrix[b.length][a.length];
  }

  isCloseGuess(guess, actualAnswer) {
    const normGuess = this.normalizeAnswer(guess);
    const normActual = this.normalizeAnswer(actualAnswer);
    if (!normGuess || !normActual || normGuess.length < 3) return false;

    const dist = this.levenshtein(normGuess, normActual);
    if (dist <= 2) return true;

    
    if (normActual.includes(normGuess) && normGuess.length >= 3) return true;
    if (normGuess.includes(normActual) && normGuess.length - normActual.length <= 6) return true;

    const similarity = 1 - (dist / Math.max(normGuess.length, normActual.length));
    return similarity >= 0.65;
  }

  checkAnswerMatch(guess, actualAnswer) {
    const normGuess = this.normalizeAnswer(guess);
    const normActual = this.normalizeAnswer(actualAnswer);

    if (normGuess === normActual) return true;

    
    const simpleGuess = guess.toLowerCase().replace(/[^a-z0-9]/g, '');
    const simpleActual = actualAnswer.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (simpleGuess === simpleActual) return true;

    
    if (normActual.length >= 5 && Math.abs(normGuess.length - normActual.length) <= 1) {
      if (this.levenshtein(normGuess, normActual) <= 1) {
        return true;
      }
    }

    return false;
  }

  evaluateGuess(playerId, guessText, timeRemaining) {
    if (!this.currentPuzzle || !guessText || typeof guessText !== 'string') return;
    const player = networkManager.players.get(playerId);
    if (!player || player.hasGuessedThisRound) return;

    
    const isInteractive = (this.selectedCategory === 'drawing' || this.selectedCategory === 'charades');
    if (isInteractive && playerId === this.activeDrawerId) return;

    const isCorrect = this.checkAnswerMatch(guessText, this.currentPuzzle.answer);

    if (isCorrect) {
      this.correctGuessCount++;
      player.hasGuessedThisRound = true;

      
      let basePoints = 40;
      if (this.correctGuessCount === 1) basePoints = 100;
      else if (this.correctGuessCount === 2) basePoints = 80;
      else if (this.correctGuessCount === 3) basePoints = 60;

      const validTime = (typeof timeRemaining === 'number' && timeRemaining > 0) ? timeRemaining : this.timeRemaining;
      const speedBonus = Math.round((validTime / this.roundDuration) * 30);
      const totalRoundPoints = basePoints + speedBonus;

      player.roundPoints = totalRoundPoints;
      player.score += totalRoundPoints;

      
      const guessPayload = {
        type: 'PLAYER_GUESSED',
        playerId: playerId,
        playerName: player.name,
        playerAvatar: player.avatar,
        isCorrect: true,
        isClose: false,
        guessText: guessText,
        points: totalRoundPoints,
        order: this.correctGuessCount,
        players: Array.from(networkManager.players.values()).map(p => ({
          id: p.id,
          name: p.name,
          avatar: p.avatar,
          score: p.score,
          hasGuessedThisRound: p.hasGuessedThisRound
        }))
      };

      networkManager.broadcast(guessPayload);
      this.handlePlayerGuessBroadcast(guessPayload);

      
      const activePlayers = Array.from(networkManager.players.values()).filter(p => p.connected);
      const eligibleGuessers = isInteractive
        ? activePlayers.filter(p => p.id !== this.activeDrawerId)
        : activePlayers;
      
      const solvedCount = eligibleGuessers.filter(p => p.hasGuessedThisRound).length;

      if (solvedCount >= eligibleGuessers.length) {
        if (this.timerInterval) clearInterval(this.timerInterval);
        setTimeout(() => this.endCurrentRound(), 1200);
      }
    } else {
      
      const isClose = this.isCloseGuess(guessText, this.currentPuzzle.answer);

      const wrongPayload = {
        type: 'PLAYER_GUESSED',
        playerId: playerId,
        playerName: player.name,
        playerAvatar: player.avatar,
        isCorrect: false,
        isClose: isClose,
        guessText: guessText
      };
      networkManager.broadcast(wrongPayload);
      this.handlePlayerGuessBroadcast(wrongPayload);
    }
  }

  handlePlayerGuessBroadcast(data) {
    if (!data) return;
    const feed = document.getElementById('live-guess-feed');
    const isMe = data.playerId === networkManager.playerId;

    if (data.isCorrect) {
      if (isMe) {
        this.hasGuessed = true;
        document.getElementById('guess-input').disabled = true;
        document.getElementById('btn-submit-guess').disabled = true;
        const feedback = document.getElementById('guess-feedback');
        feedback.textContent = `🎉 Brilliant! You guessed correctly! (+${data.points} pts)`;
        feedback.className = 'guess-feedback success';
        soundEngine.playCorrect();
        confettiEngine.burst({ count: 60 });
      }

      if (feed) {
        const item = document.createElement('div');
        item.className = 'feed-item correct';
        item.innerHTML = `<span>${data.playerAvatar} <strong>${this.escapeHtml(data.playerName)}</strong> solved it! #${data.order} (+${data.points} pts)</span>`;
        feed.prepend(item);
      }
    } else {
      if (isMe) {
        const feedback = document.getElementById('guess-feedback');
        if (data.isClose) {
          feedback.textContent = `🔥 So close! Check your spelling for "${this.escapeHtml(data.guessText)}"!`;
          feedback.className = 'guess-feedback close';
          soundEngine.playTick(true);
        } else {
          feedback.textContent = `❌ "${this.escapeHtml(data.guessText)}" is not correct, try again!`;
          feedback.className = 'guess-feedback wrong';
          soundEngine.playWrong();
        }
      }

      if (feed) {
        const item = document.createElement('div');
        item.className = 'feed-item wrong';
        item.innerHTML = `<span>${data.playerAvatar} ${this.escapeHtml(data.playerName)}: ${this.escapeHtml(data.guessText)}</span>`;
        feed.prepend(item);
      }
    }

    if (data.players) {
      this.renderLiveScoreboard(data.players);
    }
  }

  renderLiveScoreboard(players) {
    const list = document.getElementById('live-scoreboard-list');
    if (!list) return;
    list.innerHTML = '';

    const sorted = [...players].sort((a, b) => b.score - a.score);
    sorted.forEach((p, idx) => {
      const item = document.createElement('div');
      item.className = `score-row ${p.hasGuessedThisRound ? 'solved' : ''}`;
      item.innerHTML = `
        <span class="score-rank">#${idx + 1}</span>
        <span class="score-avatar">${p.avatar}</span>
        <span class="score-name">${this.escapeHtml(p.name)}</span>
        <span class="score-points">${p.score} pts</span>
      `;
      list.appendChild(item);
    });
  }

  

  endCurrentRound() {
    this.stopSongTuneHint(false);
    this.stopCameraCharades(true);

    
    const isInteractive = (this.selectedCategory === 'drawing' || this.selectedCategory === 'charades');
    if (isInteractive && this.activeDrawerId) {
      const presenter = networkManager.players.get(this.activeDrawerId);
      if (presenter) {
        const activeGuessers = Array.from(networkManager.players.values()).filter(p => p.connected && p.id !== this.activeDrawerId);
        const totalGuessers = Math.max(1, activeGuessers.length);
        const presenterBase = Math.round((this.correctGuessCount / totalGuessers) * 120);
        const finalPts = Math.max(0, presenterBase - (this.usedAudioHint ? 30 : 0));
        presenter.roundPoints = finalPts;
        presenter.score += finalPts;
      }
    }

    const resultPayload = {
      type: 'ROUND_ENDED',
      roundNumber: this.currentRound,
      totalRounds: this.puzzles.length,
      answer: this.currentPuzzle.answer,
      emojis: this.currentPuzzle.emojis || '🎬🎨',
      players: Array.from(networkManager.players.values()),
      isLastRound: this.currentRound >= this.puzzles.length
    };

    networkManager.broadcast(resultPayload);
    this.showRoundResults(resultPayload);
  }

  showRoundResults(data) {
    document.getElementById('result-answer-emojis').textContent = data.emojis;
    document.getElementById('result-answer-text').textContent = data.answer;
    document.getElementById('result-round-title').textContent = `Round ${data.roundNumber} Summary`;

    
    const container = document.getElementById('result-leaderboard');
    if (container) {
      container.innerHTML = '';
      const sorted = [...data.players].sort((a, b) => b.score - a.score);
      sorted.forEach((p, idx) => {
        const row = document.createElement('div');
        row.className = 'result-row';
        row.innerHTML = `
          <div class="result-rank">#${idx + 1}</div>
          <div class="result-player">
            <span class="result-avatar">${p.avatar}</span>
            <span class="result-name">${this.escapeHtml(p.name)}</span>
          </div>
          <div class="result-round-pts">${p.roundPoints > 0 ? `+${p.roundPoints}` : '0'}</div>
          <div class="result-total-pts">${p.score} pts</div>
        `;
        container.appendChild(row);
      });
    }

    const nextBtn = document.getElementById('btn-next-round');
    if (networkManager.isHost) {
      if (nextBtn) {
        nextBtn.classList.remove('hidden');
        nextBtn.textContent = data.isLastRound ? 'View Final Results 🏆' : 'Next Round ➡️';
      }
    } else {
      if (nextBtn) nextBtn.classList.add('hidden');
    }

    this.showScreen(this.screenRoundResult);
    soundEngine.playRoundStart();
  }

  finishGame() {
    const gameOverPayload = {
      type: 'GAME_OVER',
      players: Array.from(networkManager.players.values())
    };
    networkManager.broadcast(gameOverPayload);
    this.showGameOver(gameOverPayload);
  }

  showGameOver(data) {
    const sorted = [...data.players].sort((a, b) => b.score - a.score);
    const podiumContainer = document.getElementById('podium-container');
    const finalLeaderboard = document.getElementById('final-leaderboard');

    if (podiumContainer) {
      podiumContainer.innerHTML = '';
      const p1 = sorted[0];
      const p2 = sorted[1];
      const p3 = sorted[2];

      const renderPodiumStep = (player, place, medal, heightClass) => {
        if (!player) return '';
        return `
          <div class="podium-step ${heightClass}">
            <div class="podium-medal">${medal}</div>
            <div class="podium-avatar">${player.avatar}</div>
            <div class="podium-name">${this.escapeHtml(player.name)}</div>
            <div class="podium-score">${player.score} pts</div>
            <div class="podium-base">${place}</div>
          </div>
        `;
      };

      podiumContainer.innerHTML = `
        ${renderPodiumStep(p2, '2nd', '🥈', 'step-silver')}
        ${renderPodiumStep(p1, '1st', '👑', 'step-gold')}
        ${renderPodiumStep(p3, '3rd', '🥉', 'step-bronze')}
      `;
    }

    if (finalLeaderboard) {
      finalLeaderboard.innerHTML = '';
      sorted.forEach((p, idx) => {
        const item = document.createElement('div');
        item.className = 'final-score-row';
        item.innerHTML = `
          <span>#${idx + 1} ${p.avatar} <strong>${this.escapeHtml(p.name)}</strong></span>
          <span>${p.score} pts</span>
        `;
        finalLeaderboard.appendChild(item);
      });
    }

    
    const hostActions = document.getElementById('host-game-over-actions');
    const playerActions = document.getElementById('player-game-over-actions');
    if (networkManager.isHost) {
      if (hostActions) hostActions.classList.remove('hidden');
      if (playerActions) playerActions.classList.add('hidden');
    } else {
      if (hostActions) hostActions.classList.add('hidden');
      if (playerActions) playerActions.classList.remove('hidden');
    }

    this.showScreen(this.screenGameOver);
    soundEngine.playVictory();
    confettiEngine.burst({ count: 120 });
    setTimeout(() => confettiEngine.burst({ count: 100 }), 700);
  }

  leaveCurrentRoom(broadcast = true) {
    if (this.timerInterval) clearInterval(this.timerInterval);
    if (this.hangoutInterval) clearInterval(this.hangoutInterval);
    soundEngine.stopMovieTune();
    this.stopGroupCallMedia();
    this.stopCameraCharades(false);
    this.unmountAllVideoTiles();

    if (broadcast) {
      networkManager.leaveRoom();
    } else {
      networkManager.disconnect();
    }

    this.isHangoutMode = false;
    this.isReconfiguring = false;
    this.currentRound = 0;
    this.puzzles = [];
    this.hasGuessed = false;
    this.revealedLetters.clear();
    this.activeDrawerId = null;
    this.usedAudioHint = false;

    this.hideDrawerChoosingOverlay();
    this.hideMovieChoiceModal();
    if (this.drawingCanvas) this.drawingCanvas.clearLocal(false);
    
    
    try {
      window.history.replaceState({}, document.title, window.location.pathname);
    } catch (e) {}

    this.showScreen(this.screenHome);
  }

  

  openDeckManager() {
    this.renderCustomPuzzlesList();
    this.modalDeck.classList.remove('hidden');
  }

  renderCustomPuzzlesList() {
    const list = document.getElementById('deck-custom-list');
    const countBadge = document.getElementById('deck-custom-count');
    if (!list) return;

    const custom = window.deckManager.customPuzzles;
    if (countBadge) countBadge.textContent = `${custom.length} Custom Item${custom.length === 1 ? '' : 's'}`;

    list.innerHTML = '';
    if (custom.length === 0) {
      list.innerHTML = '<p class="empty-state">No custom puzzles added yet. Fill out the form above to add your own!</p>';
      return;
    }

    custom.forEach(p => {
      const item = document.createElement('div');
      item.className = 'deck-item';
      item.innerHTML = `
        <div class="deck-item-emojis">${p.emojis}</div>
        <div class="deck-item-info">
          <strong>${this.escapeHtml(p.answer)}</strong>
          <small class="tag tag-${p.category}">${p.category.toUpperCase()}</small>
          ${p.hint ? `<span class="deck-hint">"${this.escapeHtml(p.hint)}"</span>` : ''}
        </div>
        <button class="btn-delete-puzzle" data-id="${p.id}" title="Delete">🗑️</button>
      `;
      item.querySelector('.btn-delete-puzzle').addEventListener('click', () => {
        window.deckManager.removeCustomPuzzle(p.id);
        this.renderCustomPuzzlesList();
        this.showToast('Custom item removed', 'info');
      });
      list.appendChild(item);
    });
  }

  handleAddCustomPuzzle() {
    const emojis = document.getElementById('custom-emojis').value.trim();
    const answer = document.getElementById('custom-answer').value.trim();
    const category = document.getElementById('custom-category').value;
    const hint = document.getElementById('custom-hint').value.trim();

    if (!emojis || !answer) {
      this.showToast('Please enter both emojis and the correct answer', 'warning');
      return;
    }

    window.deckManager.addCustomPuzzle(emojis, answer, category, hint);
    document.getElementById('custom-emojis').value = '';
    document.getElementById('custom-answer').value = '';
    document.getElementById('custom-hint').value = '';

    this.renderCustomPuzzlesList();
    this.showToast('Custom puzzle added successfully! 🎉', 'success');
  }

  

  getCategoryLabel(cat) {
    switch (cat) {
      case 'movies': return '🎬 Bollywood Movie (2000+)';
      case 'songs': return '🎵 Bollywood Song';
      case 'translations': return '🇬🇧➡️🇮🇳 Bollywood in English';
      case 'drawing': return '🎨 Draw & Guess';
      case 'charades': return '🎭 Live Video Dumb Charades';
      case 'hangout': return '📹 Group Video Hangout';
      default: return '🔀 Bollywood Mix';
    }
  }

  showToast(message, type = 'info') {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    container.appendChild(toast);

    setTimeout(() => {
      toast.classList.add('fade-out');
      setTimeout(() => toast.remove(), 400);
    }, 3200);
  }

  showLoading(text = 'Loading...') {
    const overlay = document.getElementById('loading-overlay');
    const loadingText = document.getElementById('loading-text');
    if (loadingText) loadingText.textContent = text;
    if (overlay) overlay.classList.remove('hidden');
  }

  hideLoading() {
    const overlay = document.getElementById('loading-overlay');
    if (overlay) overlay.classList.add('hidden');
  }

  escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str || '';
    return div.innerHTML;
  }
}


window.addEventListener('DOMContentLoaded', () => {
  window.game = new DecodeItGame();
});

